CONTENTS = {'app/routes/admin.py': 'from __future__ import annotations\nfrom app.services.search_providers import serper_status\n\nfrom pathlib import Path\nfrom urllib.parse import urlencode\n\nfrom fastapi import APIRouter, Request\nfrom fastapi.responses import FileResponse, HTMLResponse, JSONResponse, RedirectResponse, Response\nfrom sqlalchemy import func, or_, select\nfrom sqlalchemy.exc import IntegrityError\nfrom sqlalchemy.orm import selectinload\n\nfrom ..config import settings\nfrom ..database import SessionLocal\nfrom ..models import (\n    AdminUser, Disaster, DiscoveryCandidate, DiscoverySearchTag,\n    DiscoverySourceSeed, MissingPerson, PersonCaseState, Source, Submission,\n)\nfrom ..security import verify_password\nfrom ..services.discovery import discover_candidates, generate_queries, google_search_url\nfrom ..services.wide_discovery import collect_known_source_scopes, generate_wide_queries, run_wide_discovery\nfrom ..services.search_providers import SearchProviderUnavailable, brave_status\nfrom ..services.candidate_extract import candidate_mentions_multiple_people, extract_candidate_people_names, extract_candidate_prefill\nfrom ..services.candidate_chatgpt_prefill import (\n    ChatGPTPrefillParseError,\n    build_candidate_chatgpt_prefill_prompt,\n    parse_candidate_chatgpt_prefill,\n)\nfrom ..services.openai_prefill import (\n    OpenAIPrefillError,\n    generate_openai_candidate_prefill,\n    openai_prefill_status,\n)\nfrom ..services.ai_review import build_free_ai_review_prompt, parse_free_ai_review\nfrom ..services.master_records import apply_submission_to_master\nfrom ..services.duplicates import find_duplicates\nfrom ..services.exports import build_csv, build_xlsx\nfrom ..services.files import save_image\nfrom ..services.source_images import discover_public_post_image, discover_public_post_text, download_public_source_image, is_allowed_public_image_url\nfrom ..services.source_ocr import extract_ocr_text, ocr_available\nfrom ..services.normalization import affected_location_match, canonicalize_url, detect_platform\nfrom ..services.priority_sources import (\n    custom_tag_queries,\n    discovered_source_activity,\n    normalize_facebook_source_scope,\n    priority_manual_searches,\n    priority_source_scopes,\n    source_url_for_scope,\n    user_search_tags,\n    user_source_seeds,\n)\nfrom ..services.share_cards import build_share_card\nfrom .common import admin_gate, audit, next_case_number, parse_date, parse_int, parse_time, render\n\nrouter = APIRouter()\n\n\ndef _normalize_gender(value) -> str | None:\n    folded = str(value or "").strip().casefold()\n    if folded in {"male", "m", "पुरुष"}:\n        return "Male"\n    if folded in {"female", "f", "महिला"}:\n        return "Female"\n    return None\n\n\ndef _exact_name_matches(db, disaster_id: int, name: str) -> list[MissingPerson]:\n    folded = name.strip().casefold()\n    if not folded:\n        return []\n    people = db.scalars(\n        select(MissingPerson).where(\n            MissingPerson.disaster_id == disaster_id,\n            MissingPerson.archived.is_(False),\n        )\n    ).all()\n    return [\n        person\n        for person in people\n        if person.name.strip().casefold() == folded\n        or (person.name_ne and person.name_ne.strip().casefold() == folded)\n    ]\n\n\ndef _pending_name_matches(db, disaster_id: int, name: str) -> list[Submission]:\n    folded = name.strip().casefold()\n    if not folded:\n        return []\n    submissions = db.scalars(\n        select(Submission).where(\n            Submission.disaster_id == disaster_id,\n            Submission.status == "pending",\n        )\n    ).all()\n    return [\n        item for item in submissions\n        if (item.name or "").strip().casefold() == folded\n    ]\n\n\nPERSON_CASE_STATUSES = {"missing", "found", "identified"}\n\n\ndef _person_case_status_map(db, person_ids: list[int]) -> dict[int, str]:\n    if not person_ids:\n        return {}\n    rows = db.scalars(\n        select(PersonCaseState).where(PersonCaseState.person_id.in_(person_ids))\n    ).all()\n    status_map = {row.person_id: row.status for row in rows}\n    return {person_id: status_map.get(person_id, "missing") for person_id in person_ids}\n\n\ndef _set_person_case_status(\n    db,\n    person: MissingPerson,\n    status: str,\n    note: str | None = None,\n) -> PersonCaseState:\n    normalized = str(status or "").strip().casefold()\n    if normalized not in PERSON_CASE_STATUSES:\n        raise ValueError("Invalid person case status")\n    state = db.get(PersonCaseState, person.id)\n    if state is None:\n        state = PersonCaseState(person_id=person.id, status=normalized)\n        db.add(state)\n    else:\n        state.status = normalized\n    state.note = str(note or "").strip() or None\n    if normalized != "missing":\n        # Resolved/deceased cases leave the active public missing-person list.\n        person.published = False\n    return state\n\n\ndef _source_notes_for_candidate(\n    candidate: DiscoveryCandidate,\n    source_post_text: str,\n    ocr_text: str,\n) -> str | None:\n    parts: list[str] = []\n    if source_post_text:\n        parts.append("Public post text:\\n" + source_post_text[:12_000])\n    elif candidate.snippet:\n        parts.append("Search/public snippet:\\n" + candidate.snippet)\n    if ocr_text:\n        parts.append("OCR text from reviewed source image:\\n" + ocr_text[:12_000])\n    return "\\n\\n".join(item.strip() for item in parts if item.strip()) or None\n\n\n@router.get("/admin/media/{filename}")\ndef admin_media(request: Request, filename: str):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    if Path(filename).name != filename:\n        return HTMLResponse("Not found", status_code=404)\n    with SessionLocal() as db:\n        referenced = db.scalar(\n            select(func.count()).select_from(Submission).where(Submission.photo_path == filename)\n        ) or db.scalar(\n            select(func.count()).select_from(MissingPerson).where(MissingPerson.photo_path == filename)\n        )\n        if not referenced:\n            return HTMLResponse("Not found", status_code=404)\n    path = settings.upload_dir / filename\n    if not path.is_file():\n        return HTMLResponse("Not found", status_code=404)\n    return FileResponse(path)\n\n\n@router.get("/admin/login", response_class=HTMLResponse)\ndef login_page(request: Request):\n    return render(request, "admin_login.html", error=None)\n\n\n@router.post("/admin/login", response_class=HTMLResponse)\nasync def login(request: Request):\n    form = await request.form()\n    username = str(form.get("username") or "")\n    password = str(form.get("password") or "")\n    with SessionLocal() as db:\n        admin = db.scalar(select(AdminUser).where(AdminUser.username == username, AdminUser.active.is_(True)))\n        if admin is None or not verify_password(password, admin.password_hash):\n            return render(request, "admin_login.html", error="Invalid credentials")\n        request.session["admin"] = admin.username\n        audit(db, request, "login", "admin", admin.id)\n        db.commit()\n    return RedirectResponse("/admin", status_code=303)\n\n\n@router.post("/admin/logout")\ndef logout(request: Request):\n    request.session.clear()\n    return RedirectResponse("/admin/login", status_code=303)\n\n\n@router.get("/admin", response_class=HTMLResponse)\ndef admin_dashboard(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        stats = {\n            "people": db.scalar(select(func.count(MissingPerson.id)).where(MissingPerson.archived.is_(False))) or 0,\n            "published": db.scalar(\n                select(func.count(MissingPerson.id)).where(\n                    MissingPerson.published.is_(True), MissingPerson.archived.is_(False)\n                )\n            )\n            or 0,\n            "pending": db.scalar(select(func.count(Submission.id)).where(Submission.status == "pending")) or 0,\n            "candidates": db.scalar(\n                select(func.count(DiscoveryCandidate.id)).where(DiscoveryCandidate.status == "new")\n            )\n            or 0,\n            "sources": db.scalar(select(func.count(Source.id))) or 0,\n        }\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_dashboard.html", stats=stats, disasters=disasters)\n\n\n@router.get("/admin/events", response_class=HTMLResponse)\ndef admin_events(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_events.html", disasters=disasters, error=None)\n\n\n@router.post("/admin/events")\nasync def admin_event_create(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    code = str(form.get("code") or "").strip().upper()\n    name = str(form.get("name") or "").strip()\n    start_date = parse_date(form.get("start_date"))\n    if not code or not name or not start_date:\n        return RedirectResponse("/admin/events", status_code=303)\n    with SessionLocal() as db:\n        disaster = Disaster(\n            code=code,\n            name=name,\n            disaster_type=str(form.get("disaster_type") or "flood").strip(),\n            start_date=start_date,\n            affected_locations=str(form.get("affected_locations") or "").strip(),\n            active=True,\n        )\n        db.add(disaster)\n        try:\n            db.flush()\n            audit(db, request, "create_event", "disaster", disaster.id, name)\n            db.commit()\n        except IntegrityError:\n            db.rollback()\n    return RedirectResponse("/admin/events", status_code=303)\n\n\n@router.post("/admin/events/{disaster_id}/update")\nasync def admin_event_update(request: Request, disaster_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id)\n        if disaster is None:\n            return HTMLResponse("Not found", status_code=404)\n        disaster.name = str(form.get("name") or disaster.name).strip()\n        disaster.disaster_type = str(form.get("disaster_type") or disaster.disaster_type).strip()\n        disaster.affected_locations = str(form.get("affected_locations") or "").strip()\n        disaster.active = str(form.get("active") or "") == "on"\n        audit(db, request, "update_event", "disaster", disaster.id, disaster.name)\n        db.commit()\n    return RedirectResponse("/admin/events", status_code=303)\n\n\n@router.get("/admin/people", response_class=HTMLResponse)\ndef admin_people(\n    request: Request,\n    disaster_id: int | None = None,\n    q: str = "",\n    case_status: str = "missing",\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    case_status = case_status.strip().casefold()\n    if case_status not in {"missing", "found", "identified", "all"}:\n        case_status = "missing"\n\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        stmt = (\n            select(MissingPerson)\n            .options(selectinload(MissingPerson.sources))\n            .outerjoin(PersonCaseState, PersonCaseState.person_id == MissingPerson.id)\n            .where(MissingPerson.archived.is_(False))\n            .order_by(MissingPerson.created_at.desc())\n        )\n        if disaster_id:\n            stmt = stmt.where(MissingPerson.disaster_id == disaster_id)\n        if case_status != "all":\n            stmt = stmt.where(\n                func.coalesce(PersonCaseState.status, "missing") == case_status\n            )\n        if q.strip():\n            pattern = f"%{q.strip()}%"\n            stmt = stmt.where(\n                or_(\n                    MissingPerson.name.ilike(pattern),\n                    MissingPerson.name_ne.ilike(pattern),\n                    MissingPerson.case_number.ilike(pattern),\n                )\n            )\n        people = list(db.scalars(stmt.limit(500)).all())\n        status_map = _person_case_status_map(db, [person.id for person in people])\n\n        counts: dict[str, int] = {}\n        for status_name in ("missing", "found", "identified"):\n            count_stmt = (\n                select(func.count(MissingPerson.id))\n                .select_from(MissingPerson)\n                .outerjoin(PersonCaseState, PersonCaseState.person_id == MissingPerson.id)\n                .where(\n                    MissingPerson.archived.is_(False),\n                    func.coalesce(PersonCaseState.status, "missing") == status_name,\n                )\n            )\n            if disaster_id:\n                count_stmt = count_stmt.where(MissingPerson.disaster_id == disaster_id)\n            counts[status_name] = db.scalar(count_stmt) or 0\n        counts["all"] = sum(counts.values())\n\n        return render(\n            request,\n            "admin_people.html",\n            people=people,\n            disasters=disasters,\n            selected_disaster=disaster_id,\n            q=q,\n            case_status=case_status,\n            status_map=status_map,\n            status_counts=counts,\n        )\n\n\n@router.get("/admin/people/{person_id}", response_class=HTMLResponse)\ndef admin_person(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.scalar(\n            select(MissingPerson)\n            .options(selectinload(MissingPerson.sources))\n            .where(MissingPerson.id == person_id)\n        )\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        merge_targets = list(\n            db.scalars(\n                select(MissingPerson).where(\n                    MissingPerson.disaster_id == person.disaster_id,\n                    MissingPerson.id != person.id,\n                    MissingPerson.archived.is_(False),\n                ).order_by(MissingPerson.name)\n            ).all()\n        )\n        return render(\n            request,\n            "admin_person.html",\n            person=person,\n            error=None,\n            public_url=f"{settings.public_base_url}/person/{person.case_number}",\n            merge_targets=merge_targets,\n            case_status=_person_case_status_map(db, [person.id]).get(person.id, "missing"),\n        )\n\n\n@router.post("/admin/people/{person_id}/edit")\nasync def admin_person_edit(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        person.name = str(form.get("name") or person.name).strip()\n        person.name_ne = str(form.get("name_ne") or "").strip() or None\n        person.age = parse_int(form.get("age"))\n        person.gender = _normalize_gender(form.get("gender"))\n        person.last_seen_date = parse_date(form.get("last_seen_date"))\n        person.last_seen_time = parse_time(form.get("last_seen_time"))\n        person.last_seen_location = str(form.get("last_seen_location") or "").strip()\n        person.clothing = str(form.get("clothing") or "").strip() or None\n        person.identification_details = str(form.get("identification_details") or "").strip() or None\n        person.public_contact_number = str(form.get("public_contact_number") or "").strip() or None\n        person.residential_address_private = str(form.get("residential_address_private") or "").strip() or None\n        audit(db, request, "edit_person", "person", person.id)\n        db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/status")\nasync def admin_person_status(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    status = str(form.get("case_status") or "").strip().casefold()\n    note = str(form.get("status_note") or "").strip()\n    if status not in PERSON_CASE_STATUSES:\n        return HTMLResponse("Invalid case status", status_code=400)\n\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        _set_person_case_status(db, person, status, note)\n        audit(\n            db,\n            request,\n            "update_person_case_status",\n            "person",\n            person.id,\n            f"status={status}; note={note[:300]}",\n        )\n        db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/publish")\ndef admin_publish(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person:\n            person.published = not person.published\n            audit(db, request, "publish_toggle", "person", person.id, str(person.published))\n            db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/archive")\ndef admin_archive(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person:\n            person.archived = True\n            person.published = False\n            audit(db, request, "archive_person", "person", person.id)\n            db.commit()\n    return RedirectResponse("/admin/people", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/merge")\nasync def admin_merge_person(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    target_id = parse_int(form.get("target_person_id"))\n    if not target_id or target_id == person_id:\n        return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n    with SessionLocal() as db:\n        source = db.scalar(\n            select(MissingPerson).options(selectinload(MissingPerson.sources)).where(MissingPerson.id == person_id)\n        )\n        target = db.scalar(\n            select(MissingPerson).options(selectinload(MissingPerson.sources)).where(MissingPerson.id == target_id)\n        )\n        if source is None or target is None or source.disaster_id != target.disaster_id:\n            return HTMLResponse("Invalid merge target", status_code=400)\n\n        target_urls = {item.url for item in target.sources}\n        for source_item in list(source.sources):\n            if source_item.url in target_urls:\n                db.delete(source_item)\n            else:\n                source_item.person_id = target.id\n                target_urls.add(source_item.url)\n\n        db.execute(\n            Submission.__table__.update()\n            .where(Submission.person_id == source.id)\n            .values(person_id=target.id)\n        )\n\n        # Fill only blank canonical fields. The target remains the admin-selected master record.\n        for field in [\n            "name_ne", "age", "gender", "photo_path", "residential_address_private",\n            "last_seen_date", "last_seen_time", "clothing", "identification_details",\n            "public_contact_number", "private_contact_number",\n        ]:\n            if getattr(target, field) in (None, "") and getattr(source, field) not in (None, ""):\n                setattr(target, field, getattr(source, field))\n        if not target.last_seen_location and source.last_seen_location:\n            target.last_seen_location = source.last_seen_location\n\n        source.archived = True\n        source.published = False\n        audit(\n            db,\n            request,\n            "merge_duplicate_person",\n            "person",\n            source.id,\n            f"merged_into={target.id}; target_case={target.case_number}",\n        )\n        db.commit()\n    return RedirectResponse(f"/admin/people/{target_id}", status_code=303)\n\n\n@router.post("/admin/people/{person_id}/source")\nasync def admin_add_source(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    url = canonicalize_url(str(form.get("url") or ""))\n    if not url:\n        return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n    with SessionLocal() as db:\n        if db.get(MissingPerson, person_id) is None:\n            return HTMLResponse("Not found", status_code=404)\n        existing = db.scalar(select(Source).where(Source.person_id == person_id, Source.url == url))\n        if existing is None:\n            source = Source(\n                person_id=person_id,\n                platform=str(form.get("platform") or "facebook").strip(),\n                url=url,\n                source_name=str(form.get("source_name") or "").strip() or None,\n                source_text=str(form.get("source_text") or "").strip() or None,\n            )\n            db.add(source)\n            db.flush()\n            audit(db, request, "add_source", "source", source.id, url)\n            db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n@router.get("/admin/submissions", response_class=HTMLResponse)\ndef admin_submissions(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        submissions = list(\n            db.scalars(\n                select(Submission).where(Submission.status == "pending").order_by(Submission.created_at.desc())\n            ).all()\n        )\n        duplicate_map: dict[int, list[tuple[MissingPerson, float]]] = {}\n        location_match_map: dict[int, bool] = {}\n        disasters_by_id = {d.id: d for d in db.scalars(select(Disaster)).all()}\n        for sub in submissions:\n            disaster = disasters_by_id.get(sub.disaster_id)\n            location_match_map[sub.id] = bool(\n                disaster and affected_location_match(sub.last_seen_location, disaster.affected_locations)\n            )\n            if sub.kind == "missing_report" and sub.name:\n                duplicate_map[sub.id] = find_duplicates(\n                    db,\n                    disaster_id=sub.disaster_id,\n                    name=sub.name,\n                    location=sub.last_seen_location,\n                    age=sub.age,\n                    phone=sub.public_contact_number,\n                )\n        people = list(\n            db.scalars(\n                select(MissingPerson).where(MissingPerson.archived.is_(False)).order_by(MissingPerson.name)\n            ).all()\n        )\n        people_by_disaster: dict[int, list[MissingPerson]] = {}\n        for person in people:\n            people_by_disaster.setdefault(person.disaster_id, []).append(person)\n        return render(\n            request,\n            "admin_submissions.html",\n            submissions=submissions,\n            duplicate_map=duplicate_map,\n            location_match_map=location_match_map,\n            people_by_disaster=people_by_disaster,\n        )\n\n\n@router.post("/admin/submissions/{submission_id}/approve-new")\ndef approve_submission_new(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        if sub is None or sub.status != "pending" or not sub.name:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        disaster = db.get(Disaster, sub.disaster_id)\n        if disaster is None:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        person = MissingPerson(\n            case_number=next_case_number(db, disaster),\n            disaster_id=sub.disaster_id,\n            name=sub.name,\n            name_ne=sub.name_ne,\n            age=sub.age,\n            gender=sub.gender,\n            photo_path=sub.photo_path,\n            residential_address_private=sub.residential_address_private,\n            last_seen_date=sub.last_seen_date,\n            last_seen_time=sub.last_seen_time,\n            last_seen_location=sub.last_seen_location or "Unknown",\n            clothing=sub.clothing,\n            identification_details=sub.identification_details,\n            public_contact_number=sub.public_contact_number,\n            private_contact_number=sub.reporter_phone_private,\n            published=False,\n        )\n        db.add(person)\n        db.flush()\n        sub.person_id = person.id\n        sub.status = "approved"\n        if sub.social_url:\n            db.add(\n                Source(\n                    person_id=person.id,\n                    platform=detect_platform(sub.social_url),\n                    url=sub.social_url,\n                    source_text=sub.notes,\n                )\n            )\n        audit(db, request, "approve_submission_new", "person", person.id, f"submission={sub.id}")\n        db.commit()\n        return RedirectResponse(f"/admin/people/{person.id}", status_code=303)\n\n\n@router.post("/admin/submissions/{submission_id}/attach")\nasync def attach_submission(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    person_id = parse_int(form.get("person_id"))\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        person = db.get(MissingPerson, person_id) if person_id else None\n        if sub is None or person is None:\n            return RedirectResponse("/admin/submissions", status_code=303)\n        if person.disaster_id != sub.disaster_id:\n            return HTMLResponse("Cannot attach a submission to a person from a different disaster", status_code=400)\n        if sub.status != "pending":\n            return RedirectResponse("/admin/submissions", status_code=303)\n\n        updated_fields = apply_submission_to_master(\n            person,\n            sub,\n        )\n\n        if sub.social_url:\n            existing = db.scalar(select(Source).where(Source.person_id == person.id, Source.url == sub.social_url))\n            if existing is None:\n                db.add(\n                    Source(\n                        person_id=person.id,\n                        platform=detect_platform(sub.social_url),\n                        url=sub.social_url,\n                        source_text=sub.notes,\n                    )\n                )\n        sub.person_id = person.id\n        sub.status = "attached"\n        audit(\n            db,\n            request,\n            "attach_submission",\n            "person",\n            person.id,\n            (\n                f"submission={sub.id}; "\n                f"master_fields_updated={\',\'.join(updated_fields) or \'none\'}"\n            ),\n        )\n        db.commit()\n    return RedirectResponse(f"/admin/people/{person_id}", status_code=303)\n\n\n\n@router.post(\n    "/admin/submissions/{submission_id}/edit"\n)\nasync def edit_pending_submission(\n    request: Request,\n    submission_id: int,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    with SessionLocal() as db:\n        sub = db.get(\n            Submission,\n            submission_id,\n        )\n\n        if (\n            sub is None\n            or sub.status != "pending"\n        ):\n            return RedirectResponse(\n                "/admin/submissions",\n                status_code=303,\n            )\n\n        name = str(\n            form.get("name")\n            or ""\n        ).strip()\n\n        if (\n            sub.kind == "missing_report"\n            and not name\n        ):\n            return HTMLResponse(\n                "Name is required",\n                status_code=400,\n            )\n\n        sub.name = name or sub.name\n\n        sub.name_ne = (\n            str(\n                form.get("name_ne")\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.age = parse_int(\n            form.get("age")\n        )\n\n        sub.gender = _normalize_gender(form.get("gender"))\n\n        sub.last_seen_date = parse_date(\n            form.get("last_seen_date")\n        )\n\n        sub.last_seen_time = parse_time(\n            form.get("last_seen_time")\n        )\n\n        sub.last_seen_location = (\n            str(\n                form.get(\n                    "last_seen_location"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.clothing = (\n            str(\n                form.get("clothing")\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.identification_details = (\n            str(\n                form.get(\n                    "identification_details"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        sub.public_contact_number = (\n            str(\n                form.get(\n                    "public_contact_number"\n                )\n                or ""\n            ).strip()\n            or None\n        )\n\n        photo_upload = form.get(\n            "photo"\n        )\n\n        if (\n            photo_upload is not None\n            and getattr(\n                photo_upload,\n                "filename",\n                "",\n            )\n        ):\n            try:\n                photo_path = await save_image(\n                    photo_upload,\n                    settings.upload_dir,\n                )\n            except ValueError as exc:\n                return HTMLResponse(\n                    str(exc),\n                    status_code=400,\n                )\n\n            if photo_path:\n                sub.photo_path = photo_path\n\n        audit(\n            db,\n            request,\n            "edit_pending_submission",\n            "submission",\n            sub.id,\n            "admin-reviewed extracted details",\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        "/admin/submissions",\n        status_code=303,\n    )\n\n\n@router.post("/admin/submissions/{submission_id}/reject")\ndef reject_submission(request: Request, submission_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        sub = db.get(Submission, submission_id)\n        if sub:\n            sub.status = "rejected"\n            audit(db, request, "reject_submission", "submission", sub.id)\n            db.commit()\n    return RedirectResponse("/admin/submissions", status_code=303)\n\n\n@router.get("/admin/discovery", response_class=HTMLResponse)\ndef discovery_page(\n    request: Request,\n    disaster_id: int | None = None,\n    platform: str = "facebook",\n    view: str = "review",\n    q: str = "",\n    wide_queries: int | None = None,\n    wide_raw: int | None = None,\n    wide_added: int | None = None,\n    wide_error: int | None = None,\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    allowed_views = {"review", "relevant", "irrelevant", "processed"}\n    view = view.casefold().strip()\n    if view not in allowed_views:\n        view = "review"\n\n    with SessionLocal() as db:\n        disasters = list(\n            db.scalars(\n                select(Disaster).order_by(\n                    Disaster.active.desc(),\n                    Disaster.start_date.desc(),\n                )\n            ).all()\n        )\n        selected = (\n            db.get(Disaster, disaster_id)\n            if disaster_id\n            else next((d for d in disasters if d.active), disasters[0] if disasters else None)\n        )\n\n        queries = (\n            generate_queries(selected, platform=platform)\n            if selected\n            else []\n        )\n\n        wide_provider_status = serper_status()\n        wide_query_plan: list[str] = []\n        published_urls: set[str] = set()\n        queue_counts = {\n            "review": 0,\n            "relevant": 0,\n            "irrelevant": 0,\n            "processed": 0,\n        }\n        candidates: list[DiscoveryCandidate] = []\n\n        if selected:\n            if platform == "facebook":\n                scopes = collect_known_source_scopes(db, selected.id)\n                custom_tag_rows = user_search_tags(db, selected.id, platform)\n                manual_source_rows = user_source_seeds(db, selected.id, platform)\n                wide_query_plan = generate_wide_queries(\n                    selected,\n                    source_scopes=scopes,\n                    custom_tags=[row.tag for row in custom_tag_rows],\n                    manual_source_scopes=[row.scope for row in manual_source_rows],\n                    manual_sources=[(row.label, row.scope) for row in manual_source_rows],\n                )\n\n            published_urls = set(\n                db.scalars(\n                    select(Source.url)\n                    .join(MissingPerson, Source.person_id == MissingPerson.id)\n                    .where(\n                        MissingPerson.disaster_id == selected.id,\n                        MissingPerson.published.is_(True),\n                        MissingPerson.archived.is_(False),\n                    )\n                ).all()\n            )\n\n            base_conditions = [\n                DiscoveryCandidate.disaster_id == selected.id,\n                DiscoveryCandidate.platform == platform,\n            ]\n\n            status_groups = {\n                "review": ["new", "needs_ai"],\n                "relevant": ["relevant"],\n                "irrelevant": ["irrelevant", "rejected"],\n                "processed": ["reviewed"],\n            }\n\n            for key, statuses in status_groups.items():\n                count_stmt = (\n                    select(func.count(DiscoveryCandidate.id))\n                    .where(*base_conditions)\n                    .where(DiscoveryCandidate.status.in_(statuses))\n                )\n                if key in {"review", "relevant"} and published_urls:\n                    count_stmt = count_stmt.where(\n                        DiscoveryCandidate.url.notin_(published_urls)\n                    )\n                queue_counts[key] = db.scalar(count_stmt) or 0\n\n            stmt = (\n                select(DiscoveryCandidate)\n                .where(*base_conditions)\n                .where(DiscoveryCandidate.status.in_(status_groups[view]))\n                .order_by(DiscoveryCandidate.found_at.desc())\n            )\n\n            if view in {"review", "relevant"} and published_urls:\n                stmt = stmt.where(\n                    DiscoveryCandidate.url.notin_(published_urls)\n                )\n\n            if q.strip():\n                pattern = f"%{q.strip()}%"\n                stmt = stmt.where(\n                    or_(\n                        DiscoveryCandidate.title.ilike(pattern),\n                        DiscoveryCandidate.snippet.ilike(pattern),\n                    )\n                )\n\n            candidates = list(db.scalars(stmt.limit(300)).all())\n\n        base_params = {\n            "disaster_id": selected.id if selected else "",\n            "platform": platform,\n        }\n        queue_links = {\n            key: "/admin/discovery?" + urlencode(\n                {**base_params, "view": key, **({"q": q.strip()} if q.strip() else {})}\n            )\n            for key in allowed_views\n        }\n        clear_search_url = "/admin/discovery?" + urlencode(\n            {**base_params, "view": view}\n        )\n\n        priority_searches = []\n        custom_tags = []\n        custom_tag_searches = []\n        manual_sources = []\n        auto_sources = []\n        if selected and platform == "facebook":\n            priority_searches = [\n                {\n                    **item,\n                    "url": google_search_url(item["query"], selected.start_date),\n                    "secondary_url": google_search_url(item["secondary_query"], selected.start_date),\n                }\n                for item in priority_manual_searches(selected)\n            ]\n            custom_tags = user_search_tags(db, selected.id, platform)\n            for tag_row in custom_tags:\n                custom_tag_searches.append(\n                    {\n                        "row": tag_row,\n                        "queries": [\n                            (query, google_search_url(query, selected.start_date))\n                            for query in custom_tag_queries(selected, [tag_row.tag])\n                        ],\n                    }\n                )\n            manual_sources = user_source_seeds(db, selected.id, platform)\n            auto_sources = discovered_source_activity(db, selected.id)\n            already_scoped = {scope.casefold() for scope in priority_source_scopes()} | {\n                row.scope.casefold() for row in manual_sources\n            }\n            auto_sources = [\n                item for item in auto_sources\n                if str(item["scope"]).casefold() not in already_scoped\n            ]\n\n        return render(\n            request,\n            "admin_discovery.html",\n            disasters=disasters,\n            selected=selected,\n            platform=platform,\n            view=view,\n            q=q,\n            queue_counts=queue_counts,\n            queue_links=queue_links,\n            clear_search_url=clear_search_url,\n            queries=[(item, google_search_url(item, selected.start_date)) for item in queries] if selected else [],\n            priority_searches=priority_searches,\n            custom_tags=custom_tags,\n            custom_tag_searches=custom_tag_searches,\n            manual_sources=manual_sources,\n            auto_sources=auto_sources,\n            candidates=candidates,\n            bot_message=None,\n            wide_stats=(\n                {"queries": wide_queries, "raw": wide_raw, "added": wide_added}\n                if wide_queries is not None\n                else None\n            ),\n            wide_provider_status=wide_provider_status,\n            wide_query_plan=wide_query_plan,\n            wide_error=bool(wide_error),\n        )\n\n\n@router.post("/admin/discovery/run")\nasync def discovery_run(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    platform = str(form.get("platform") or "facebook")\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id) if disaster_id else None\n        if disaster is None:\n            return RedirectResponse("/admin/discovery", status_code=303)\n        added = discover_candidates(db, disaster, platform=platform)\n        audit(db, request, "run_discovery_bot", "disaster", disaster.id, f"platform={platform}; added={added}")\n        db.commit()\n    return RedirectResponse(f"/admin/discovery?disaster_id={disaster_id}&platform={platform}", status_code=303)\n\n\n\n@router.post("/admin/wide-discovery/run")\nasync def wide_discovery_run(\n    request: Request,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    disaster_id = parse_int(\n        form.get("disaster_id")\n    )\n\n    with SessionLocal() as db:\n        disaster = (\n            db.get(\n                Disaster,\n                disaster_id,\n            )\n            if disaster_id\n            else None\n        )\n\n        if disaster is None:\n            return RedirectResponse(\n                "/admin/discovery",\n                status_code=303,\n            )\n\n        try:\n            stats = run_wide_discovery(\n                db,\n                disaster,\n            )\n        except SearchProviderUnavailable:\n            return RedirectResponse(\n                (\n                    "/admin/discovery"\n                    f"?disaster_id={disaster_id}"\n                    "&platform=facebook"\n                    "&wide_error=1"\n                ),\n                status_code=303,\n            )\n\n        audit(\n            db,\n            request,\n            "run_wide_discovery",\n            "disaster",\n            disaster.id,\n            (\n                f"queries={stats[\'queries\']}; "\n                f"raw={stats[\'raw_results\']}; "\n                f"needs_ai={stats[\'needs_ai\']}"\n            ),\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        (\n            "/admin/discovery"\n            f"?disaster_id={disaster_id}"\n            "&platform=facebook"\n            f"&wide_queries={stats[\'queries\']}"\n            f"&wide_raw={stats[\'raw_results\']}"\n            f"&wide_added={stats[\'needs_ai\']}"\n        ),\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/search-tags")\nasync def discovery_add_search_tag(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    platform = str(form.get("platform") or "facebook").strip().casefold()\n    tag = " ".join(str(form.get("tag") or "").split())\n    if not disaster_id or not tag:\n        return RedirectResponse("/admin/discovery", status_code=303)\n    if len(tag) > 255:\n        return HTMLResponse("Search tag is too long", status_code=400)\n\n    with SessionLocal() as db:\n        existing = db.scalar(\n            select(DiscoverySearchTag).where(\n                DiscoverySearchTag.disaster_id == disaster_id,\n                DiscoverySearchTag.platform == platform,\n                func.lower(DiscoverySearchTag.tag) == tag.casefold(),\n            )\n        )\n        if existing is None:\n            row = DiscoverySearchTag(\n                disaster_id=disaster_id,\n                platform=platform,\n                tag=tag,\n                active=True,\n            )\n            db.add(row)\n            db.flush()\n            audit(db, request, "add_discovery_search_tag", "discovery_search_tag", row.id, tag)\n        else:\n            existing.active = True\n        db.commit()\n    return RedirectResponse(\n        f"/admin/discovery?disaster_id={disaster_id}&platform={platform}#custom-search-tags",\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/search-tags/{tag_id}/delete")\nasync def discovery_delete_search_tag(request: Request, tag_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    platform = str(form.get("platform") or "facebook").strip().casefold()\n    with SessionLocal() as db:\n        row = db.get(DiscoverySearchTag, tag_id)\n        if row is not None:\n            row.active = False\n            audit(db, request, "disable_discovery_search_tag", "discovery_search_tag", row.id, row.tag)\n            disaster_id = row.disaster_id\n            platform = row.platform\n            db.commit()\n    return RedirectResponse(\n        f"/admin/discovery?disaster_id={disaster_id or \'\'}&platform={platform}#custom-search-tags",\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/source-seeds")\nasync def discovery_add_source_seed(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    platform = str(form.get("platform") or "facebook").strip().casefold()\n    label = " ".join(str(form.get("label") or "").split())\n    source_value = str(form.get("source") or "").strip()\n    scope = normalize_facebook_source_scope(source_value)\n    if not disaster_id or platform != "facebook" or not scope:\n        return HTMLResponse(\n            "Enter a valid public Facebook page/group URL or page/group scope.",\n            status_code=400,\n        )\n    label = label or scope\n    if len(label) > 255 or len(scope) > 255:\n        return HTMLResponse("Source name is too long", status_code=400)\n\n    with SessionLocal() as db:\n        existing = db.scalar(\n            select(DiscoverySourceSeed).where(\n                DiscoverySourceSeed.disaster_id == disaster_id,\n                DiscoverySourceSeed.platform == platform,\n                func.lower(DiscoverySourceSeed.scope) == scope.casefold(),\n            )\n        )\n        if existing is None:\n            row = DiscoverySourceSeed(\n                disaster_id=disaster_id,\n                platform=platform,\n                label=label,\n                scope=scope,\n                source_url=source_url_for_scope(scope),\n                active=True,\n            )\n            db.add(row)\n            db.flush()\n            audit(db, request, "add_discovery_source_seed", "discovery_source_seed", row.id, scope)\n        else:\n            existing.active = True\n            existing.label = label\n            existing.source_url = source_url_for_scope(scope)\n        db.commit()\n    return RedirectResponse(\n        f"/admin/discovery?disaster_id={disaster_id}&platform={platform}#source-finder",\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/source-seeds/{source_id}/delete")\nasync def discovery_delete_source_seed(request: Request, source_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    platform = str(form.get("platform") or "facebook").strip().casefold()\n    with SessionLocal() as db:\n        row = db.get(DiscoverySourceSeed, source_id)\n        if row is not None:\n            row.active = False\n            audit(db, request, "disable_discovery_source_seed", "discovery_source_seed", row.id, row.scope)\n            disaster_id = row.disaster_id\n            platform = row.platform\n            db.commit()\n    return RedirectResponse(\n        f"/admin/discovery?disaster_id={disaster_id or \'\'}&platform={platform}#source-finder",\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/manual")\nasync def discovery_manual(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    disaster_id = parse_int(form.get("disaster_id"))\n    url = canonicalize_url(str(form.get("url") or ""))\n    platform = str(form.get("platform") or "facebook").strip()\n    title = str(form.get("title") or "").strip()\n    manual_text = str(form.get("snippet") or "").strip()\n    search_query = str(form.get("search_query") or "").strip()\n\n    if not disaster_id or not url:\n        return RedirectResponse("/admin/discovery", status_code=303)\n\n    with SessionLocal() as db:\n        existing = db.scalar(\n            select(DiscoveryCandidate).where(\n                DiscoveryCandidate.disaster_id == disaster_id,\n                DiscoveryCandidate.url == url,\n            )\n        )\n\n        if existing is None:\n            query_value = (\n                f"manual:{search_query}"\n                if search_query\n                else "manual-url"\n            )\n            candidate = DiscoveryCandidate(\n                disaster_id=disaster_id,\n                platform=platform,\n                query=query_value,\n                url=url,\n                title=title or None,\n                snippet=manual_text or None,\n            )\n            db.add(candidate)\n            db.flush()\n            audit(\n                db,\n                request,\n                "add_manual_candidate",\n                "discovery_candidate",\n                candidate.id,\n                (\n                    f"url={url}; "\n                    f"search_context={search_query or \'direct\'}"\n                ),\n            )\n        else:\n            candidate = existing\n            changes: list[str] = []\n\n            # Human-entered context can enrich an existing automated result\n            # without destroying the original indexed evidence.\n            if title and not (candidate.title or "").strip():\n                candidate.title = title\n                changes.append("title")\n\n            if manual_text:\n                current = (candidate.snippet or "").strip()\n                if manual_text not in current:\n                    candidate.snippet = (\n                        f"{current}\\\\n\\\\n[Manual context]\\\\n{manual_text}"\n                        if current\n                        else manual_text\n                    )\n                    changes.append("context")\n\n            audit(\n                db,\n                request,\n                "update_manual_candidate_context",\n                "discovery_candidate",\n                candidate.id,\n                (\n                    f"url={url}; "\n                    f"search_context={search_query or \'direct\'}; "\n                    f"changes={\',\'.join(changes) or \'none\'}"\n                ),\n            )\n\n        db.commit()\n        candidate_id = candidate.id\n\n    return RedirectResponse(\n        f"/admin/discovery/{candidate_id}",\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/{candidate_id}/status")\nasync def discovery_candidate_status(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    action = str(form.get("status_action") or "").strip().casefold()\n    current_view = str(form.get("view") or "review").strip().casefold()\n    platform = str(form.get("platform") or "facebook").strip()\n    q = str(form.get("q") or "").strip()\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n\n        if action == "relevant":\n            candidate.status = "relevant"\n        elif action == "irrelevant":\n            candidate.status = "irrelevant"\n        elif action == "restore":\n            candidate.status = "needs_ai"\n        elif action == "processed":\n            candidate.status = "reviewed"\n        elif action == "reopen":\n            candidate.status = "relevant"\n        else:\n            return HTMLResponse("Invalid discovery status", status_code=400)\n\n        audit(\n            db,\n            request,\n            "classify_discovery_candidate",\n            "discovery_candidate",\n            candidate.id,\n            f"status={candidate.status}",\n        )\n        db.commit()\n\n        params = {\n            "disaster_id": candidate.disaster_id,\n            "platform": platform,\n            "view": current_view if current_view in {"review", "relevant", "irrelevant", "processed"} else "review",\n        }\n        if q:\n            params["q"] = q\n\n    if action == "relevant":\n        # Relevant is the hand-off point from discovery triage into\n        # detailed source review and ChatGPT-assisted prefill.\n        return RedirectResponse(\n            f"/admin/discovery/{candidate_id}#chatgpt-prefill",\n            status_code=303,\n        )\n\n    return RedirectResponse(\n        "/admin/discovery?" + urlencode(params),\n        status_code=303,\n    )\n\n\n@router.get("/admin/discovery/{candidate_id}/public-details")\nasync def discovery_candidate_public_details(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return JSONResponse({"error": "not found"}, status_code=404)\n        disaster = db.get(Disaster, candidate.disaster_id)\n        if disaster is None:\n            return JSONResponse({"error": "unknown disaster"}, status_code=404)\n\n        source_text = ""\n        if candidate.platform == "facebook":\n            source_text = (await discover_public_post_text(candidate.url)) or ""\n\n        evidence_text = source_text or candidate.snippet or ""\n        prefill = extract_candidate_prefill(\n            candidate,\n            disaster,\n            source_text=source_text,\n        )\n        people = extract_candidate_people_names(\n            candidate,\n            source_text=source_text,\n        )\n        multiple_people = candidate_mentions_multiple_people(\n            candidate,\n            source_text=source_text,\n        )\n\n        return JSONResponse(\n            {\n                "text": evidence_text,\n                "full_public_text_available": bool(source_text),\n                "people": people,\n                "multiple_people": multiple_people,\n                "age": prefill.get("age"),\n                "last_seen_location": prefill.get("last_seen_location"),\n                "public_contact_number": prefill.get("public_contact_number"),\n            }\n        )\n\n\n@router.get("/admin/discovery/{candidate_id}/duplicate-check")\ndef discovery_candidate_duplicate_check(\n    request: Request,\n    candidate_id: int,\n    name: str = "",\n    location: str = "",\n    age: int | None = None,\n    phone: str = "",\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return JSONResponse({"error": "not found"}, status_code=404)\n\n        exact = _exact_name_matches(db, candidate.disaster_id, name)\n        fuzzy = find_duplicates(\n            db,\n            disaster_id=candidate.disaster_id,\n            name=name,\n            location=location,\n            age=age,\n            phone=phone,\n        ) if name.strip() else []\n        pending = _pending_name_matches(db, candidate.disaster_id, name)\n\n        fuzzy_map = {person.id: score for person, score in fuzzy}\n        people = []\n        seen_ids: set[int] = set()\n        for person in exact + [person for person, _ in fuzzy]:\n            if person.id in seen_ids:\n                continue\n            seen_ids.add(person.id)\n            has_source = db.scalar(\n                select(Source.id).where(\n                    Source.person_id == person.id,\n                    Source.url == candidate.url,\n                )\n            ) is not None\n            people.append(\n                {\n                    "id": person.id,\n                    "case_number": person.case_number,\n                    "name": person.name,\n                    "age": person.age,\n                    "last_seen_location": person.last_seen_location,\n                    "score": 100.0 if person in exact else fuzzy_map.get(person.id, 0.0),\n                    "exact_name": person in exact,\n                    "source_already_attached": has_source,\n                }\n            )\n\n        return JSONResponse(\n            {\n                "people": people,\n                "pending": [\n                    {"id": item.id, "name": item.name}\n                    for item in pending[:5]\n                ],\n            }\n        )\n\n\n@router.get(\n    "/admin/discovery/{candidate_id}",\n    response_class=HTMLResponse,\n)\nasync def discovery_candidate_review(\n    request: Request,\n    candidate_id: int,\n    created: int | None = None,\n    attached: int | None = None,\n    batch_created: int | None = None,\n    batch_duplicates: int | None = None,\n    batch_skipped: int | None = None,\n):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n\n        disaster = db.get(Disaster, candidate.disaster_id)\n        if disaster is None:\n            return HTMLResponse("Unknown disaster", status_code=404)\n\n        source_image_url = None\n        source_post_text = ""\n        ocr_text = ""\n        ocr_detail = None\n\n        if candidate.platform == "facebook":\n            source_post_text = (await discover_public_post_text(candidate.url)) or ""\n            source_image_url = await discover_public_post_image(candidate.url)\n\n        if source_image_url:\n            if ocr_available():\n                ocr_dir = settings.upload_dir / "_ocr_preview"\n                ocr_filename = await download_public_source_image(\n                    source_image_url,\n                    ocr_dir,\n                )\n                if ocr_filename:\n                    local_path = ocr_dir / ocr_filename\n                    result = extract_ocr_text(local_path)\n                    ocr_text = result.text\n                    ocr_detail = result.detail\n                    try:\n                        local_path.unlink(missing_ok=True)\n                        ocr_dir.rmdir()\n                    except OSError:\n                        pass\n            else:\n                ocr_detail = (\n                    "Local OCR is not available yet. Install Tesseract OCR "\n                    "and the Nepali language data to read poster text automatically."\n                )\n\n        prefill = extract_candidate_prefill(\n            candidate,\n            disaster,\n            ocr_text=ocr_text,\n            source_text=source_post_text,\n        )\n        chatgpt_prefill_prompt = build_candidate_chatgpt_prefill_prompt(\n            disaster,\n            candidate,\n            source_post_text=source_post_text,\n            ocr_text=ocr_text,\n        )\n        detected_people = extract_candidate_people_names(\n            candidate,\n            source_text=source_post_text,\n            ocr_text=ocr_text,\n        )\n        multiple_people_signal = candidate_mentions_multiple_people(\n            candidate,\n            source_text=source_post_text,\n            ocr_text=ocr_text,\n        )\n        if prefill.get("name") and prefill["name"].casefold() not in {\n            item.casefold() for item in detected_people\n        }:\n            detected_people.insert(0, prefill["name"])\n\n        source_submission_names = {\n            (item or "").strip().casefold()\n            for item in db.scalars(\n                select(Submission.name).where(\n                    Submission.disaster_id == candidate.disaster_id,\n                    Submission.social_url == candidate.url,\n                    Submission.status != "rejected",\n                )\n            ).all()\n            if item\n        }\n        remaining_people = [\n            item for item in detected_people\n            if item.casefold() not in source_submission_names\n        ]\n\n        if (\n            created\n            and remaining_people\n            and str(prefill.get("name") or "").strip().casefold()\n            in source_submission_names\n        ):\n            # After one person is created from a multi-person source, move the\n            # review form to the next explicit name. Other fields remain review\n            # suggestions and must still be checked by the operator.\n            prefill["name"] = remaining_people[0]\n\n        exact_duplicates = _exact_name_matches(\n            db,\n            candidate.disaster_id,\n            str(prefill.get("name") or ""),\n        )\n        pending_duplicates = _pending_name_matches(\n            db,\n            candidate.disaster_id,\n            str(prefill.get("name") or ""),\n        )\n\n        db.commit()\n\n        return render(\n            request,\n            "admin_discovery_review.html",\n            candidate=candidate,\n            prefill=prefill,\n            source_image_url=source_image_url,\n            source_post_text=source_post_text,\n            ocr_text=ocr_text,\n            ocr_detail=ocr_detail,\n            detected_people=detected_people,\n            remaining_people=remaining_people,\n            multiple_people_signal=multiple_people_signal,\n            exact_duplicates=exact_duplicates,\n            pending_duplicates=pending_duplicates,\n            source_submission_names=source_submission_names,\n            chatgpt_prefill_prompt=chatgpt_prefill_prompt,\n            openai_prefill_status=openai_prefill_status(),\n            created=bool(created),\n            attached=bool(attached),\n            batch_created=batch_created or 0,\n            batch_duplicates=batch_duplicates or 0,\n            batch_skipped=batch_skipped or 0,\n        )\n\n\n@router.post("/admin/discovery/{candidate_id}/openai-prefill")\nasync def discovery_openai_prefill(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return JSONResponse({"error": "not found"}, status_code=404)\n        if candidate.status != "relevant":\n            return JSONResponse(\n                {"error": "Mark this source Relevant before running AI Prefill."},\n                status_code=409,\n            )\n        disaster = db.get(Disaster, candidate.disaster_id)\n        if disaster is None:\n            return JSONResponse({"error": "unknown disaster"}, status_code=404)\n\n        source_post_text = ""\n        source_image_url = None\n        ocr_text = ""\n\n        if candidate.platform == "facebook":\n            source_post_text = (await discover_public_post_text(candidate.url)) or ""\n            source_image_url = await discover_public_post_image(candidate.url)\n\n        # Local OCR is still useful when installed. The OpenAI request may also\n        # receive the reviewed public source image, with strict instructions to\n        # read written text only and never identify/infer from appearance.\n        if source_image_url and ocr_available():\n            ocr_dir = settings.upload_dir / "_ocr_openai_prefill"\n            ocr_filename = await download_public_source_image(source_image_url, ocr_dir)\n            if ocr_filename:\n                local_path = ocr_dir / ocr_filename\n                result = extract_ocr_text(local_path)\n                ocr_text = result.text\n                try:\n                    local_path.unlink(missing_ok=True)\n                    ocr_dir.rmdir()\n                except OSError:\n                    pass\n\n        try:\n            payload = await generate_openai_candidate_prefill(\n                disaster,\n                candidate,\n                source_post_text=source_post_text,\n                ocr_text=ocr_text,\n                source_image_url=source_image_url,\n            )\n        except OpenAIPrefillError as exc:\n            return JSONResponse({"error": str(exc)}, status_code=503)\n\n        audit(\n            db,\n            request,\n            "openai_candidate_prefill",\n            "discovery_candidate",\n            candidate.id,\n            (\n                f"model={payload.get(\'model\')}; "\n                f"people={len(payload.get(\'people\') or [])}; "\n                f"input_tokens={(payload.get(\'usage\') or {}).get(\'input_tokens\', 0)}; "\n                f"output_tokens={(payload.get(\'usage\') or {}).get(\'output_tokens\', 0)}"\n            ),\n        )\n        db.commit()\n        return JSONResponse(payload)\n\n\n@router.post("/admin/discovery/{candidate_id}/chatgpt-prefill/parse")\nasync def discovery_chatgpt_prefill_parse(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    raw = str(form.get("result_json") or "")\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return JSONResponse({"error": "not found"}, status_code=404)\n    try:\n        payload = parse_candidate_chatgpt_prefill(raw)\n    except ChatGPTPrefillParseError as exc:\n        return JSONResponse({"error": str(exc)}, status_code=400)\n    return JSONResponse(payload)\n\n\n@router.post("/admin/discovery/{candidate_id}/chatgpt-prefill/batch")\nasync def discovery_chatgpt_prefill_batch(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    form = await request.form()\n    raw = str(form.get("result_json") or "")\n    source_post_text = str(form.get("source_post_text") or "").strip()\n    ocr_text = str(form.get("ocr_text") or "").strip()\n\n    try:\n        payload = parse_candidate_chatgpt_prefill(raw)\n    except ChatGPTPrefillParseError as exc:\n        return HTMLResponse(f"Could not parse ChatGPT prefill: {exc}", status_code=400)\n\n    created = 0\n    duplicates = 0\n    skipped = 0\n\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n        if candidate.status in {"irrelevant", "rejected"}:\n            return HTMLResponse("Restore this candidate before creating submissions.", status_code=409)\n\n        notes = _source_notes_for_candidate(candidate, source_post_text, ocr_text)\n        source_image_url = None\n        photo_path = None\n        if candidate.platform == "facebook":\n            source_image_url = await discover_public_post_image(candidate.url)\n        if source_image_url and is_allowed_public_image_url(source_image_url):\n            photo_path = await download_public_source_image(source_image_url, settings.upload_dir)\n\n        for person_data in payload["people"]:\n            name = str(person_data.get("name") or "").strip()\n            if not name:\n                skipped += 1\n                continue\n\n            same_source = db.scalar(\n                select(Submission.id).where(\n                    Submission.disaster_id == candidate.disaster_id,\n                    Submission.social_url == candidate.url,\n                    func.lower(Submission.name) == name.casefold(),\n                    Submission.status != "rejected",\n                )\n            )\n            if same_source:\n                skipped += 1\n                continue\n\n            # Batch mode is deliberately conservative. Exact existing/pending\n            # names need the operator\'s individual attach-vs-new decision.\n            if _exact_name_matches(db, candidate.disaster_id, name) or _pending_name_matches(\n                db, candidate.disaster_id, name\n            ):\n                duplicates += 1\n                continue\n\n            db.add(\n                Submission(\n                    disaster_id=candidate.disaster_id,\n                    kind="missing_report",\n                    status="pending",\n                    name=name,\n                    name_ne=str(person_data.get("name_ne") or "").strip() or None,\n                    age=parse_int(person_data.get("age")),\n                    gender=_normalize_gender(person_data.get("gender")),\n                    photo_path=photo_path,\n                    last_seen_date=parse_date(person_data.get("last_seen_date")),\n                    last_seen_time=parse_time(person_data.get("last_seen_time")),\n                    last_seen_location=str(person_data.get("last_seen_location") or "").strip() or None,\n                    clothing=str(person_data.get("clothing") or "").strip() or None,\n                    identification_details=str(person_data.get("identification_details") or "").strip() or None,\n                    public_contact_number=str(person_data.get("public_contact_number") or "").strip() or None,\n                    social_url=candidate.url,\n                    notes=notes,\n                )\n            )\n            created += 1\n\n        candidate.status = "relevant"\n        audit(\n            db,\n            request,\n            "batch_chatgpt_prefill_to_submissions",\n            "discovery_candidate",\n            candidate.id,\n            f"created={created}; duplicates={duplicates}; skipped={skipped}",\n        )\n        db.commit()\n\n    params = urlencode(\n        {\n            "batch_created": created,\n            "batch_duplicates": duplicates,\n            "batch_skipped": skipped,\n        }\n    )\n    return RedirectResponse(\n        f"/admin/discovery/{candidate_id}?{params}#chatgpt-prefill",\n        status_code=303,\n    )\n\n\n@router.post("/admin/discovery/{candidate_id}/submission")\nasync def discovery_to_submission(request: Request, candidate_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n\n    form = await request.form()\n    with SessionLocal() as db:\n        candidate = db.get(DiscoveryCandidate, candidate_id)\n        if candidate is None:\n            return HTMLResponse("Not found", status_code=404)\n        if candidate.status in {"irrelevant", "rejected"}:\n            return HTMLResponse(\n                "Restore this discovery candidate before creating a submission.",\n                status_code=409,\n            )\n\n        name = str(form.get("name") or "").strip()\n        location = str(form.get("last_seen_location") or "").strip()\n        if not name or not location:\n            return RedirectResponse(f"/admin/discovery/{candidate_id}", status_code=303)\n\n        ocr_text = str(form.get("ocr_text") or "").strip()\n        source_post_text = str(form.get("source_post_text") or "").strip()\n        notes = _source_notes_for_candidate(candidate, source_post_text, ocr_text)\n\n        exact_duplicates = _exact_name_matches(db, candidate.disaster_id, name)\n        duplicate_action = str(form.get("duplicate_action") or "").strip().casefold()\n\n        if exact_duplicates:\n            if duplicate_action.startswith("attach:"):\n                try:\n                    person_id = int(duplicate_action.split(":", 1)[1])\n                except ValueError:\n                    return HTMLResponse("Invalid duplicate action", status_code=400)\n                person = next((item for item in exact_duplicates if item.id == person_id), None)\n                if person is None:\n                    return HTMLResponse("Duplicate target does not match this name", status_code=409)\n\n                existing_source = db.scalar(\n                    select(Source).where(\n                        Source.person_id == person.id,\n                        Source.url == candidate.url,\n                    )\n                )\n                if existing_source is None:\n                    db.add(\n                        Source(\n                            person_id=person.id,\n                            platform=candidate.platform,\n                            url=candidate.url,\n                            source_text=notes,\n                        )\n                    )\n                elif notes and not existing_source.source_text:\n                    existing_source.source_text = notes\n\n                candidate.status = "relevant"\n                audit(\n                    db,\n                    request,\n                    "attach_discovery_source_existing_person",\n                    "person",\n                    person.id,\n                    candidate.url,\n                )\n                db.commit()\n                return RedirectResponse(\n                    f"/admin/discovery/{candidate_id}?attached=1#person-entry-form",\n                    status_code=303,\n                )\n\n            if duplicate_action != "continue":\n                return HTMLResponse(\n                    "Duplicate name detected. Choose the existing person to attach this source, "\n                    "or explicitly confirm that this is a different person with the same name.",\n                    status_code=409,\n                )\n\n        pending_duplicates = _pending_name_matches(\n            db,\n            candidate.disaster_id,\n            name,\n        )\n        if pending_duplicates and duplicate_action != "continue":\n            return HTMLResponse(\n                "A pending submission already uses this name. Review the pending entry first, "\n                "or explicitly confirm that this should be a separate entry.",\n                status_code=409,\n            )\n\n        source_image_url = str(form.get("source_image_url") or "").strip()\n        include_source_image = str(form.get("include_source_image") or "") == "1"\n        photo_path = None\n\n        if include_source_image and source_image_url and is_allowed_public_image_url(source_image_url):\n            photo_path = await download_public_source_image(\n                source_image_url,\n                settings.upload_dir,\n            )\n\n        same_source_submissions = db.scalars(\n            select(Submission).where(\n                Submission.disaster_id == candidate.disaster_id,\n                Submission.social_url == candidate.url,\n                Submission.status != "rejected",\n            )\n        ).all()\n        existing_same_source = any(\n            (item.name or "").strip().casefold() == name.casefold()\n            for item in same_source_submissions\n        )\n        if existing_same_source:\n            return HTMLResponse(\n                "This person already has a submission from this exact public source.",\n                status_code=409,\n            )\n\n        sub = Submission(\n            disaster_id=candidate.disaster_id,\n            kind="missing_report",\n            name=name,\n            photo_path=photo_path,\n            name_ne=str(form.get("name_ne") or "").strip() or None,\n            age=parse_int(form.get("age")),\n            gender=_normalize_gender(form.get("gender")),\n            last_seen_date=parse_date(form.get("last_seen_date")),\n            last_seen_time=parse_time(form.get("last_seen_time")),\n            last_seen_location=location,\n            clothing=str(form.get("clothing") or "").strip() or None,\n            identification_details=str(form.get("identification_details") or "").strip() or None,\n            public_contact_number=str(form.get("public_contact_number") or "").strip() or None,\n            social_url=candidate.url,\n            notes=notes,\n        )\n        db.add(sub)\n\n        # Keep the source in Relevant until an operator explicitly marks the\n        # whole post processed. One post may contain several missing people.\n        candidate.status = "relevant"\n        db.flush()\n        audit(\n            db,\n            request,\n            "candidate_to_submission",\n            "submission",\n            sub.id,\n            candidate.url,\n        )\n        db.commit()\n\n    return RedirectResponse(\n        f"/admin/discovery/{candidate_id}?created=1#person-entry-form",\n        status_code=303,\n    )\n\n\n@router.get(\n    "/admin/ai-review",\n    response_class=HTMLResponse,\n)\ndef discovery_ai_review_page(\n    request: Request,\n    disaster_id: int,\n    platform: str = "facebook",\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    with SessionLocal() as db:\n        disaster = db.get(\n            Disaster,\n            disaster_id,\n        )\n\n        if disaster is None:\n            return HTMLResponse(\n                "Unknown disaster",\n                status_code=404,\n            )\n\n        candidates = list(\n            db.scalars(\n                select(DiscoveryCandidate)\n                .where(\n                    DiscoveryCandidate.disaster_id\n                    == disaster.id,\n                    DiscoveryCandidate.platform\n                    == platform,\n                    DiscoveryCandidate.status.in_(\n                        ["new", "needs_ai", "relevant"]\n                    ),\n                )\n                .order_by(\n                    DiscoveryCandidate.found_at.desc()\n                )\n                .limit(100)\n            ).all()\n        )\n\n        prompt = build_free_ai_review_prompt(\n            disaster,\n            candidates,\n        )\n\n        return render(\n            request,\n            "admin_ai_review.html",\n            disaster=disaster,\n            platform=platform,\n            candidates=candidates,\n            prompt=prompt,\n        )\n\n\n@router.post(\n    "/admin/ai-review/import"\n)\nasync def discovery_ai_review_import(\n    request: Request,\n):\n    gate = admin_gate(request)\n\n    if gate:\n        return gate\n\n    form = await request.form()\n\n    disaster_id = parse_int(\n        form.get("disaster_id")\n    )\n\n    platform = str(\n        form.get("platform") or "facebook"\n    ).strip()\n\n    raw_result = str(\n        form.get("result_json") or ""\n    ).strip()\n\n    if not disaster_id or not raw_result:\n        return HTMLResponse(\n            "Missing AI review data",\n            status_code=400,\n        )\n\n    try:\n        results = parse_free_ai_review(\n            raw_result\n        )\n    except ValueError:\n        return HTMLResponse(\n            "Invalid AI review JSON. "\n            "Return to Free AI Review and paste "\n            "the JSON response exactly.",\n            status_code=400,\n        )\n\n    created = 0\n    rejected = 0\n    uncertain = 0\n\n    downloaded_images: dict[str, str | None] = {}\n\n    with SessionLocal() as db:\n        disaster = db.get(\n            Disaster,\n            disaster_id,\n        )\n\n        if disaster is None:\n            return HTMLResponse(\n                "Unknown disaster",\n                status_code=404,\n            )\n\n        for result in results:\n            candidate = db.get(\n                DiscoveryCandidate,\n                result["candidate_id"],\n            )\n\n            # AI output never gets authority to change\n            # disaster/source identity.\n            if candidate is None:\n                continue\n\n            if (\n                candidate.disaster_id\n                != disaster.id\n            ):\n                continue\n\n            if candidate.platform != platform:\n                continue\n\n            if candidate.status not in {\n                "new",\n                "needs_ai",\n                "relevant",\n            }:\n                continue\n\n            decision = result["decision"]\n\n            if decision == "reject":\n                candidate.status = "irrelevant"\n                rejected += 1\n                continue\n\n            if decision == "uncertain":\n                uncertain += 1\n                continue\n\n            accepted_person = False\n\n            for person_data in result["people"]:\n                name = str(\n                    person_data.get("name")\n                    or ""\n                ).strip()\n\n                if not name:\n                    continue\n\n                accepted_person = True\n\n                existing = db.scalar(\n                    select(Submission.id).where(\n                        Submission.disaster_id\n                        == disaster.id,\n                        Submission.social_url\n                        == candidate.url,\n                        Submission.name\n                        == name,\n                    )\n                )\n\n                if existing:\n                    continue\n\n                image_url = str(\n                    person_data.get(\n                        "image_url"\n                    )\n                    or ""\n                ).strip()\n\n                photo_path = None\n\n                if (\n                    image_url\n                    and is_allowed_public_image_url(\n                        image_url\n                    )\n                ):\n                    if (\n                        image_url\n                        not in downloaded_images\n                    ):\n                        downloaded_images[\n                            image_url\n                        ] = (\n                            await download_public_source_image(\n                                image_url,\n                                settings.upload_dir,\n                            )\n                        )\n\n                    photo_path = (\n                        downloaded_images[\n                            image_url\n                        ]\n                    )\n\n                reason = result.get(\n                    "reason"\n                ) or ""\n\n                confidence = result.get(\n                    "confidence"\n                )\n\n                notes = (\n                    candidate.snippet\n                    or ""\n                ).strip()\n\n                ai_note = (\n                    f"Free AI review: {reason}"\n                )\n\n                if confidence is not None:\n                    ai_note += (\n                        f" | confidence={confidence}"\n                    )\n\n                if (\n                    image_url\n                    and is_allowed_public_image_url(\n                        image_url\n                    )\n                ):\n                    ai_note += (\n                        f" | source_image_url={image_url}"\n                    )\n\n                if notes:\n                    notes = (\n                        notes\n                        + "\\n\\n"\n                        + ai_note\n                    )\n                else:\n                    notes = ai_note\n\n                submission = Submission(\n                    disaster_id=disaster.id,\n                    kind="missing_report",\n                    name=name,\n                    photo_path=photo_path,\n                    name_ne=(\n                        str(\n                            person_data.get(\n                                "name_ne"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    age=parse_int(\n                        person_data.get("age")\n                    ),\n                    gender=_normalize_gender(person_data.get("gender")),\n                    last_seen_date=parse_date(\n                        person_data.get(\n                            "last_seen_date"\n                        )\n                    ),\n                    last_seen_time=parse_time(\n                        person_data.get(\n                            "last_seen_time"\n                        )\n                    ),\n                    last_seen_location=(\n                        str(\n                            person_data.get(\n                                "last_seen_location"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    clothing=(\n                        str(\n                            person_data.get(\n                                "clothing"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    identification_details=(\n                        str(\n                            person_data.get(\n                                "identification_details"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    public_contact_number=(\n                        str(\n                            person_data.get(\n                                "public_contact_number"\n                            )\n                            or ""\n                        ).strip()\n                        or None\n                    ),\n                    social_url=candidate.url,\n                    notes=notes,\n                )\n\n                db.add(submission)\n                created += 1\n\n            if accepted_person:\n                candidate.status = "reviewed"\n\n        audit(\n            db,\n            request,\n            "import_free_ai_review",\n            "disaster",\n            disaster.id,\n            (\n                f"platform={platform}; "\n                f"submissions={created}; "\n                f"rejected={rejected}; "\n                f"uncertain={uncertain}"\n            ),\n        )\n\n        db.commit()\n\n    return RedirectResponse(\n        "/admin/submissions",\n        status_code=303,\n    )\n\n\n@router.get("/admin/export", response_class=HTMLResponse)\ndef export_page(request: Request):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        disasters = list(db.scalars(select(Disaster).order_by(Disaster.start_date.desc())).all())\n        return render(request, "admin_export.html", disasters=disasters)\n\n\n@router.get("/admin/export/{file_type}")\ndef export_data(request: Request, file_type: str, disaster_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    if file_type not in {"csv", "xlsx"}:\n        return HTMLResponse("Unsupported export", status_code=400)\n    with SessionLocal() as db:\n        disaster = db.get(Disaster, disaster_id)\n        if disaster is None:\n            return HTMLResponse("Unknown disaster", status_code=404)\n        if file_type == "csv":\n            data = build_csv(db, disaster_id)\n            media = "text/csv; charset=utf-8"\n        else:\n            data = build_xlsx(db, disaster_id)\n            media = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"\n        audit(db, request, "export", "disaster", disaster_id, file_type)\n        db.commit()\n        filename = f"{disaster.code.lower()}-missing-people.{file_type}"\n        return Response(\n            data,\n            media_type=media,\n            headers={"Content-Disposition": f\'attachment; filename="{filename}"\'},\n        )\n\n\n@router.get("/admin/people/{person_id}/share-card")\ndef share_card(request: Request, person_id: int):\n    gate = admin_gate(request)\n    if gate:\n        return gate\n    with SessionLocal() as db:\n        person = db.get(MissingPerson, person_id)\n        if person is None:\n            return HTMLResponse("Not found", status_code=404)\n        image = build_share_card(person)\n        audit(db, request, "generate_share_card", "person", person.id)\n        db.commit()\n        return Response(\n            image,\n            media_type="image/png",\n            headers={"Content-Disposition": f\'inline; filename="{person.case_number}.png"\'},\n        )\n', 'app/templates/admin_discovery_review.html': '{% extends "base.html" %}\n{% block content %}\n\n<h1>Review Discovery Candidate</h1>\n\n{% if created %}\n<div class="card" style="border:2px solid #2f855a">\n  <strong>Pending entry created.</strong>\n  This post remains in Relevant until you confirm that every missing person in the post has been handled.\n</div>\n{% endif %}\n\n{% if attached %}\n<div class="card" style="border:2px solid #2f855a">\n  <strong>Source attached to the existing person.</strong>\n  No duplicate missing-person entry was created.\n</div>\n{% endif %}\n\n<div class="card">\n  <p>\n    <span class="badge">{{ candidate.platform }}</span>\n    <span class="badge">{{ candidate.status }}</span>\n    <a href="{{ candidate.url }}" target="_blank" rel="noopener noreferrer">\n      Open original public post\n    </a>\n  </p>\n\n  <h2>{{ candidate.title or \'Untitled result\' }}</h2>\n\n  <h3>Public post content available to the system</h3>\n  {% if source_post_text %}\n  <pre class="wrap">{{ source_post_text }}</pre>\n  <p class="muted">\n    Retrieved from public post metadata without logging in. Facebook may still withhold or truncate some content.\n  </p>\n  {% else %}\n  <pre class="wrap">{{ candidate.snippet or \'\' }}</pre>\n  <p class="muted">\n    Facebook did not expose fuller public text, so this is the best indexed text available to the system.\n  </p>\n  {% endif %}\n\n  {% if candidate.status in [\'new\', \'needs_ai\'] %}\n  <div class="inline" style="margin-top:12px">\n    <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n      <input type="hidden" name="status_action" value="relevant">\n      <input type="hidden" name="platform" value="{{ candidate.platform }}">\n      <input type="hidden" name="view" value="review">\n      <button>✓ Mark Relevant</button>\n    </form>\n    <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n      <input type="hidden" name="status_action" value="irrelevant">\n      <input type="hidden" name="platform" value="{{ candidate.platform }}">\n      <input type="hidden" name="view" value="review">\n      <button class="secondary">Mark Irrelevant</button>\n    </form>\n  </div>\n  {% elif candidate.status in [\'irrelevant\', \'rejected\'] %}\n  <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n    <input type="hidden" name="status_action" value="restore">\n    <input type="hidden" name="platform" value="{{ candidate.platform }}">\n    <input type="hidden" name="view" value="irrelevant">\n    <button>Restore to Review</button>\n  </form>\n  {% elif candidate.status == \'reviewed\' %}\n  <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n    <input type="hidden" name="status_action" value="reopen">\n    <input type="hidden" name="platform" value="{{ candidate.platform }}">\n    <input type="hidden" name="view" value="processed">\n    <button>Reopen This Post</button>\n  </form>\n  {% endif %}\n</div>\n\n{% if candidate.status == \'relevant\' %}\n<div class="card" id="chatgpt-prefill" style="border:2px solid #3182ce">\n  <h2>AI Prefill</h2>\n\n  {% if openai_prefill_status.available %}\n  <p>\n    Press one button. The backend sends the reviewed public source evidence to the OpenAI API once, extracts <strong>all explicitly named missing people</strong>, and fills the form below automatically.\n  </p>\n  <p class="muted">\n    Model: <strong>{{ openai_prefill_status.model }}</strong>. The request uses the indexed snippet, public post text, OCR text, and the public source image when available. Image use is restricted to reading written text only; the AI is instructed never to identify or infer anything from a face or appearance.\n  </p>\n  <div class="inline">\n    <button type="button" id="run-openai-prefill">✨ AI Prefill All People</button>\n    <span id="openai-prefill-status" class="muted"></span>\n  </div>\n  {% else %}\n  <div class="notice">\n    <strong>Backend AI Prefill is not configured.</strong>\n    {{ openai_prefill_status.detail }}\n  </div>\n  {% endif %}\n\n  {% if batch_created or batch_duplicates or batch_skipped %}\n  <div class="notice" style="margin-top:12px">\n    Batch result: <strong>{{ batch_created }}</strong> pending entries created.\n    {% if batch_duplicates %}<strong>{{ batch_duplicates }}</strong> duplicate-name cases were left for individual review.{% endif %}\n    {% if batch_skipped %}<strong>{{ batch_skipped }}</strong> incomplete/already-entered records were skipped.{% endif %}\n  </div>\n  {% endif %}\n\n  <div id="chatgpt-multiple-people" style="display:none; margin-top:14px">\n    <h3>People found in this post</h3>\n    <p class="muted">\n      One AI request extracts the whole post. Use any person\'s button to load that person\'s complete details into the form. After you create one entry, this list is kept in this browser tab so you can add the next person without calling the AI again.\n    </p>\n    <p class="muted">If ChatGPT found multiple missing people in this post, each extracted person is listed here separately.</p>\n    <div id="chatgpt-people-list"></div>\n    <div class="inline" style="margin-top:10px">\n      <button type="button" id="chatgpt-add-another">+ Add another missing person from this post</button>\n      <select id="chatgpt-person-picker" style="max-width:420px"></select>\n    </div>\n  </div>\n\n  <div id="chatgpt-source-notes" class="muted" style="display:none; margin-top:12px"></div>\n  <div id="openai-usage" class="muted" style="display:none; margin-top:6px"></div>\n\n  <form method="post" action="/admin/discovery/{{ candidate.id }}/chatgpt-prefill/batch" id="chatgpt-batch-form" style="margin-top:12px">\n    <input type="hidden" name="result_json" id="chatgpt-batch-json">\n    {% if source_post_text %}<textarea name="source_post_text" style="display:none">{{ source_post_text }}</textarea>{% endif %}\n    {% if ocr_text %}<textarea name="ocr_text" style="display:none">{{ ocr_text }}</textarea>{% endif %}\n    <button type="submit" id="chatgpt-batch-button" disabled>Create All Non-Duplicate People as Pending Entries</button>\n  </form>\n  <p class="muted">\n    Batch mode creates all usable people from this one post in a single action. Exact existing/pending names are not auto-attached or duplicated; they stay for individual operator review.\n  </p>\n\n  <details style="margin-top:14px">\n    <summary>Manual ChatGPT fallback / troubleshooting</summary>\n    <p class="muted">\n      Use this only if the backend API is unavailable. Copy the prepared prompt into ChatGPT, then paste the JSON result. The automatic button above is the normal workflow.\n    </p>\n    <div class="inline">\n      <button type="button" id="copy-chatgpt-prefill">Copy ChatGPT Prefill Prompt</button>\n      <a href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">Open ChatGPT</a>\n    </div>\n    <span id="chatgpt-copy-status" class="muted"></span>\n    <details style="margin-top:12px">\n      <summary>Show prepared prompt</summary>\n      <textarea id="chatgpt-prefill-prompt" rows="18" readonly>{{ chatgpt_prefill_prompt }}</textarea>\n    </details>\n    <label style="margin-top:14px">Paste ChatGPT JSON result</label>\n    <textarea\n      id="chatgpt-prefill-json"\n      rows="10"\n      placeholder=\'{"people":[{"name":"...","age":null,"gender":null,"last_seen_date":null,"last_seen_time":null,"last_seen_location":"...","clothing":null,"identification_details":"...","public_contact_number":"..."}],"source_notes":null}\'\n    ></textarea>\n    <button type="button" id="apply-chatgpt-prefill">Apply ChatGPT Prefill</button>\n    <span id="chatgpt-prefill-status" class="muted"></span>\n  </details>\n</div>\n{% endif %}\n\n{% if multiple_people_signal %}\n<div class="card" style="border:2px solid #b7791f">\n  <h2>⚠ Possible multiple missing people in this post</h2>\n  <p>\n    The public text indicates that this source may report more than one missing person.\n    {% if detected_people|length > 1 %}\n      The system found <strong>{{ detected_people|length }}</strong> explicit names.\n    {% endif %}\n    Treat these as review suggestions, not automatic identity decisions.\n  </p>\n  {% if candidate.status == \'relevant\' and openai_prefill_status.available %}\n  <button type="button" id="multiple-add-another">+ Add another missing person from this post</button>\n  <p class="muted">If AI Prefill has not run yet, this button runs it once for the whole post and then loads the next extracted person into the form.</p>\n  {% endif %}\n  {% if detected_people %}\n  <ul>\n    {% for person_name in detected_people %}\n    <li>\n      {{ person_name }}\n      {% if person_name.casefold() in source_submission_names %}\n        <span class="badge">entry already created from this post</span>\n      {% endif %}\n    </li>\n    {% endfor %}\n  </ul>\n  {% else %}\n  <p class="muted">\n    The post uses plural/family wording, but the system could not safely separate every person\'s name.\n    Review the public text and source image for additional explicitly named people.\n  </p>\n  {% endif %}\n\n  {% if remaining_people %}\n  <p><strong>Still to review from this source:</strong> {{ remaining_people|join(\', \') }}</p>\n  {% else %}\n  <p><strong>All detected names already have an entry from this source.</strong></p>\n  {% endif %}\n</div>\n{% endif %}\n\n{% if source_image_url %}\n<div class="card">\n  <h2>Picture found in public source</h2>\n  <img\n    src="{{ source_image_url }}"\n    alt="Image attached to the public missing-person post"\n    style="max-width:520px; max-height:520px; object-fit:contain; border-radius:8px"\n  >\n  <p class="muted">\n    Source evidence only. OCR may read written text from this image, but the system does not identify a person from their face or infer identity from appearance.\n  </p>\n</div>\n{% endif %}\n\n{% if ocr_text or ocr_detail %}\n<div class="card">\n  <h2>Text detected in source image</h2>\n  {% if ocr_detail %}<p class="muted">{{ ocr_detail }}</p>{% endif %}\n  {% if ocr_text %}\n  <pre class="wrap">{{ ocr_text }}</pre>\n  {% else %}\n  <p>No OCR text was detected.</p>\n  {% endif %}\n</div>\n{% endif %}\n\n<form method="post" action="/admin/discovery/{{ candidate.id }}/submission" class="card" id="person-entry-form">\n  <h2>Create or attach missing-person record</h2>\n  <p class="muted">\n    {% if candidate.status == \'relevant\' %}\n      The values below begin with the local rule-based fallback. Use the ChatGPT Prefill card above for the recommended extraction, then review every field before creating anything.\n    {% else %}\n      Review every field. If the same name already exists, the system will warn you and let you attach this new source link instead of creating a duplicate person.\n    {% endif %}\n  </p>\n\n  {% if source_post_text %}\n  <textarea name="source_post_text" style="display:none">{{ source_post_text }}</textarea>\n  {% endif %}\n  {% if ocr_text %}\n  <textarea name="ocr_text" style="display:none">{{ ocr_text }}</textarea>\n  {% endif %}\n\n  {% if multiple_people_signal and remaining_people %}\n  <label>Choose a detected person from this post</label>\n  <select id="detected-person-picker">\n    <option value="">Select a name or type manually below</option>\n    {% for person_name in remaining_people %}\n    <option value="{{ person_name }}">{{ person_name }}</option>\n    {% endfor %}\n  </select>\n  <p class="muted">Selecting a name changes only the Name field. Re-check age, location, contact and all other details for that specific person.</p>\n  {% endif %}\n\n  <div class="inline">\n    <div>\n      <label>Name *</label>\n      <input id="person-name" name="name" value="{{ prefill.name or \'\' }}" required>\n    </div>\n    <div>\n      <label>Nepali name</label>\n      <input id="person-name-ne" name="name_ne" value="{{ prefill.name_ne or \'\' }}">\n    </div>\n    <div>\n      <label>Age</label>\n      <input id="person-age" type="number" name="age" value="{{ prefill.age or \'\' }}">\n    </div>\n  </div>\n\n  <div\n    id="duplicate-warning"\n    class="card"\n    style="{% if exact_duplicates or pending_duplicates %}display:block;{% else %}display:none;{% endif %} border:2px solid #c05621; margin-top:12px"\n  >\n    {% if exact_duplicates %}\n      <h3>⚠ Possible duplicate person</h3>\n      <p>\n        <strong>The same name already exists in this disaster.</strong>\n        If this is another public link for the same person, attach the source instead of creating a duplicate person.\n      </p>\n      {% for item in exact_duplicates %}\n      <label style="display:block; margin:8px 0">\n        <input type="radio" name="duplicate_action" value="attach:{{ item.id }}" required>\n        Attach this source to {{ item.case_number }} — {{ item.name }}\n        {% if item.last_seen_location %} — {{ item.last_seen_location }}{% endif %}\n      </label>\n      {% endfor %}\n      <label style="display:block; margin:8px 0">\n        <input type="radio" name="duplicate_action" value="continue" required>\n        This is a different person with the same name. Continue with a separate pending entry.\n      </label>\n    {% elif pending_duplicates %}\n      <h3>⚠ Pending duplicate-name warning</h3>\n      <p>\n        A pending submission already uses this name. Check Pending Submissions before making another record.\n      </p>\n      <ul>\n        {% for item in pending_duplicates %}\n        <li>Submission #{{ item.id }} — {{ item.name }}</li>\n        {% endfor %}\n      </ul>\n      <label style="display:block; margin:8px 0">\n        <input type="radio" name="duplicate_action" value="continue" required>\n        I reviewed the pending match and still want a separate pending entry.\n      </label>\n    {% endif %}\n  </div>\n\n  <div class="inline">\n    <div>\n      <label>Gender</label>\n      <select id="person-gender" name="gender">\n        <option value="" {% if not prefill.gender %}selected{% endif %}>Unknown</option>\n        <option value="Male" {% if prefill.gender == \'Male\' %}selected{% endif %}>Male</option>\n        <option value="Female" {% if prefill.gender == \'Female\' %}selected{% endif %}>Female</option>\n      </select>\n    </div>\n    <div>\n      <label>Last-seen date</label>\n      <input id="person-date" type="date" name="last_seen_date" value="{{ prefill.last_seen_date or \'\' }}">\n    </div>\n    <div>\n      <label>Last-seen time</label>\n      <input id="person-time" type="time" name="last_seen_time" value="{{ prefill.last_seen_time or \'\' }}">\n    </div>\n  </div>\n\n  <label>Last-seen / affected location *</label>\n  <input id="person-location" name="last_seen_location" value="{{ prefill.last_seen_location or \'\' }}" required>\n\n  <label>Clothing</label>\n  <textarea id="person-clothing" name="clothing">{{ prefill.clothing or \'\' }}</textarea>\n\n  <label>Identification / source details</label>\n  <textarea id="person-identification" name="identification_details" rows="10">{{ prefill.identification_details or \'\' }}</textarea>\n\n  <label>Public information contact</label>\n  <input id="person-phone" name="public_contact_number" value="{{ prefill.public_contact_number or \'\' }}">\n\n  {% if source_image_url %}\n  <input type="hidden" name="source_image_url" value="{{ source_image_url }}">\n  <p>\n    <label>\n      <input type="checkbox" name="include_source_image" value="1" checked>\n      Include this reviewed source image in the pending missing-person record\n    </label>\n  </p>\n  {% endif %}\n\n  {% if candidate.status not in [\'irrelevant\', \'rejected\'] %}\n  <button id="create-entry-button">Create Pending Entry</button>\n  {% else %}\n  <p class="muted">Restore this candidate to review before creating a submission.</p>\n  {% endif %}\n</form>\n\n{% if candidate.status not in [\'irrelevant\', \'rejected\', \'reviewed\'] %}\n<div class="card">\n  <h2>Finished reviewing this post?</h2>\n  <p>\n    Only mark the post processed after every missing person mentioned in it has either been entered, attached to an existing person, or intentionally skipped after review.\n  </p>\n  <form method="post" action="/admin/discovery/{{ candidate.id }}/status">\n    <input type="hidden" name="status_action" value="processed">\n    <input type="hidden" name="platform" value="{{ candidate.platform }}">\n    <input type="hidden" name="view" value="relevant">\n    <button>✓ Mark Whole Post Processed</button>\n  </form>\n</div>\n{% endif %}\n\n<p class="muted">\n  The system reads only public text and written text detected in source images. It does not use facial recognition or infer identity from appearance.\n</p>\n\n<script>\n(function () {\n  const candidateId = {{ candidate.id }};\n  const cacheKey = `missing-person-ai-prefill-${candidateId}`;\n  const alreadyEnteredNames = new Set({{ source_submission_names|list|tojson }});\n\n  const nameInput = document.getElementById(\'person-name\');\n  const ageInput = document.getElementById(\'person-age\');\n  const locationInput = document.getElementById(\'person-location\');\n  const phoneInput = document.getElementById(\'person-phone\');\n  const warning = document.getElementById(\'duplicate-warning\');\n  const picker = document.getElementById(\'detected-person-picker\');\n  const nameNeInput = document.getElementById(\'person-name-ne\');\n  const genderInput = document.getElementById(\'person-gender\');\n  const dateInput = document.getElementById(\'person-date\');\n  const timeInput = document.getElementById(\'person-time\');\n  const clothingInput = document.getElementById(\'person-clothing\');\n  const identificationInput = document.getElementById(\'person-identification\');\n\n  const apiRun = document.getElementById(\'run-openai-prefill\');\n  const apiStatus = document.getElementById(\'openai-prefill-status\');\n  const apiUsage = document.getElementById(\'openai-usage\');\n  const multipleAddAnother = document.getElementById(\'multiple-add-another\');\n  const aiAddAnother = document.getElementById(\'chatgpt-add-another\');\n\n  const aiPrompt = document.getElementById(\'chatgpt-prefill-prompt\');\n  const aiJson = document.getElementById(\'chatgpt-prefill-json\');\n  const aiApply = document.getElementById(\'apply-chatgpt-prefill\');\n  const aiStatus = document.getElementById(\'chatgpt-prefill-status\');\n  const aiCopy = document.getElementById(\'copy-chatgpt-prefill\');\n  const aiCopyStatus = document.getElementById(\'chatgpt-copy-status\');\n  const aiPeopleBox = document.getElementById(\'chatgpt-multiple-people\');\n  const aiPeopleList = document.getElementById(\'chatgpt-people-list\');\n  const aiPeoplePicker = document.getElementById(\'chatgpt-person-picker\');\n  const aiSourceNotes = document.getElementById(\'chatgpt-source-notes\');\n  const aiBatchForm = document.getElementById(\'chatgpt-batch-form\');\n  const aiBatchJson = document.getElementById(\'chatgpt-batch-json\');\n  const aiBatchButton = document.getElementById(\'chatgpt-batch-button\');\n\n  let aiPayload = null;\n  let aiPeople = [];\n  let activeAiIndex = 0;\n  let timer = null;\n\n  function folded(value) {\n    return String(value || \'\').trim().toLocaleLowerCase();\n  }\n\n  function escapeHtml(value) {\n    const div = document.createElement(\'div\');\n    div.textContent = value == null ? \'\' : String(value);\n    return div.innerHTML;\n  }\n\n  function setField(element, value) {\n    if (!element) return;\n    element.value = value == null ? \'\' : String(value);\n  }\n\n  function applyAiPerson(person, index) {\n    if (!person || typeof person !== \'object\') return;\n    activeAiIndex = Number.isInteger(index) ? index : Math.max(0, aiPeople.indexOf(person));\n    setField(nameInput, person.name);\n    setField(nameNeInput, person.name_ne);\n    setField(ageInput, person.age);\n    setField(genderInput, [\'Male\', \'Female\'].includes(person.gender) ? person.gender : \'\');\n    setField(dateInput, person.last_seen_date);\n    setField(timeInput, person.last_seen_time);\n    setField(locationInput, person.last_seen_location);\n    setField(clothingInput, person.clothing);\n    setField(identificationInput, person.identification_details);\n    setField(phoneInput, person.public_contact_number);\n    if (aiPeoplePicker) aiPeoplePicker.value = String(activeAiIndex);\n    scheduleCheck();\n    const entryForm = document.getElementById(\'person-entry-form\');\n    if (entryForm) entryForm.scrollIntoView({behavior: \'smooth\', block: \'start\'});\n  }\n\n  function payloadForBatch() {\n    if (!aiPayload || !Array.isArray(aiPayload.people)) return \'\';\n    return JSON.stringify({\n      people: aiPayload.people,\n      source_notes: aiPayload.source_notes || null\n    });\n  }\n\n  function savePayload(payload) {\n    try {\n      sessionStorage.setItem(cacheKey, JSON.stringify(payload));\n    } catch (error) {\n      // Browser storage is an optimization only. The current page still works.\n    }\n  }\n\n  function renderAiPeople(payload, options = {}) {\n    const people = Array.isArray(payload && payload.people) ? payload.people : [];\n    if (!people.length) return false;\n\n    aiPayload = payload;\n    aiPeople = people;\n    if (!options.fromCache) savePayload(payload);\n\n    if (aiBatchJson) aiBatchJson.value = payloadForBatch();\n    if (aiBatchButton) aiBatchButton.disabled = false;\n\n    if (aiPeoplePicker) {\n      aiPeoplePicker.innerHTML = \'\';\n      aiPeople.forEach((person, index) => {\n        const option = document.createElement(\'option\');\n        option.value = String(index);\n        const name = (person && person.name) ? person.name : `Person ${index + 1}`;\n        const age = person && person.age != null ? `, age ${person.age}` : \'\';\n        const done = alreadyEnteredNames.has(folded(name)) ? \' ✓ entry already created\' : \'\';\n        option.textContent = `${index + 1}. ${name}${age}${done}`;\n        aiPeoplePicker.appendChild(option);\n      });\n    }\n\n    if (aiPeopleList) {\n      aiPeopleList.innerHTML = \'\';\n      aiPeople.forEach((person, index) => {\n        const name = (person && person.name) ? person.name : `Person ${index + 1}`;\n        const entered = alreadyEnteredNames.has(folded(name));\n        const wrapper = document.createElement(\'div\');\n        wrapper.style.margin = \'8px 0\';\n        wrapper.innerHTML = `<button type="button" data-ai-person="${index}">${entered ? \'Review\' : \'Add / review\'} ${escapeHtml(name)}</button> ${entered ? \'<span class="badge">entry already created from this post</span>\' : \'\'}`;\n        aiPeopleList.appendChild(wrapper);\n      });\n      aiPeopleList.querySelectorAll(\'[data-ai-person]\').forEach((button) => {\n        button.addEventListener(\'click\', () => {\n          const index = Number(button.getAttribute(\'data-ai-person\'));\n          if (Number.isInteger(index) && aiPeople[index]) applyAiPerson(aiPeople[index], index);\n        });\n      });\n    }\n\n    if (aiPeopleBox) aiPeopleBox.style.display = \'block\';\n\n    if (aiSourceNotes) {\n      if (payload.source_notes) {\n        aiSourceNotes.textContent = `AI source note: ${payload.source_notes}`;\n        aiSourceNotes.style.display = \'block\';\n      } else {\n        aiSourceNotes.textContent = \'\';\n        aiSourceNotes.style.display = \'none\';\n      }\n    }\n\n    if (apiUsage && payload.usage) {\n      const usage = payload.usage || {};\n      const model = payload.model || \'OpenAI model\';\n      apiUsage.textContent = `${model} • ${usage.input_tokens || 0} input tokens • ${usage.output_tokens || 0} output tokens`;\n      apiUsage.style.display = \'block\';\n    }\n\n    const preferredIndex = aiPeople.findIndex((person) => !alreadyEnteredNames.has(folded(person && person.name)));\n    applyAiPerson(aiPeople[preferredIndex >= 0 ? preferredIndex : 0], preferredIndex >= 0 ? preferredIndex : 0);\n    return true;\n  }\n\n  function loadNextUnenteredPerson() {\n    if (!aiPeople.length) return false;\n    for (let offset = 1; offset <= aiPeople.length; offset += 1) {\n      const index = (activeAiIndex + offset) % aiPeople.length;\n      const name = folded(aiPeople[index] && aiPeople[index].name);\n      if (!name || !alreadyEnteredNames.has(name)) {\n        applyAiPerson(aiPeople[index], index);\n        return true;\n      }\n    }\n    return false;\n  }\n\n  async function runBackendPrefill() {\n    if (!apiRun && !multipleAddAnother) return false;\n    if (apiRun) apiRun.disabled = true;\n    if (apiStatus) apiStatus.textContent = \'Reading the whole post and extracting every named missing person…\';\n    try {\n      const response = await fetch(\n        `/admin/discovery/${candidateId}/openai-prefill`,\n        {method: \'POST\', credentials: \'same-origin\'}\n      );\n      const payload = await response.json();\n      if (!response.ok) throw new Error(payload.error || \'Backend AI Prefill failed.\');\n      if (!renderAiPeople(payload)) throw new Error(\'No usable missing-person records were returned.\');\n      if (apiStatus) {\n        const count = aiPeople.length;\n        apiStatus.textContent = count > 1\n          ? `Done. ${count} missing people were extracted in one request. Choose a person below or create all non-duplicates at once.`\n          : \'Done. The extracted details were pasted into the form below.\';\n      }\n      return true;\n    } catch (error) {\n      if (apiStatus) apiStatus.textContent = `AI Prefill failed: ${error.message}`;\n      return false;\n    } finally {\n      if (apiRun) apiRun.disabled = false;\n    }\n  }\n\n  async function addAnotherFromPost() {\n    if (!aiPeople.length) {\n      const ok = await runBackendPrefill();\n      if (!ok) return;\n    }\n    if (!loadNextUnenteredPerson() && apiStatus) {\n      apiStatus.textContent = \'All AI-extracted names from this post already have an entry from this source, or no additional person remains.\';\n    }\n  }\n\n  function restoreCachedPayload() {\n    try {\n      const raw = sessionStorage.getItem(cacheKey);\n      if (!raw) return;\n      const payload = JSON.parse(raw);\n      if (renderAiPeople(payload, {fromCache: true}) && apiStatus) {\n        apiStatus.textContent = \'Restored the earlier AI extraction for this post. No new API request was made.\';\n      }\n    } catch (error) {\n      try { sessionStorage.removeItem(cacheKey); } catch (ignored) {}\n    }\n  }\n\n  async function copyAiPrompt() {\n    if (!aiPrompt) return;\n    try {\n      await navigator.clipboard.writeText(aiPrompt.value);\n      if (aiCopyStatus) aiCopyStatus.textContent = \'Prompt copied.\';\n    } catch (error) {\n      aiPrompt.focus();\n      aiPrompt.select();\n      document.execCommand(\'copy\');\n      if (aiCopyStatus) aiCopyStatus.textContent = \'Prompt copied.\';\n    }\n  }\n\n  async function applyAiJson() {\n    if (!aiJson || !aiStatus) return;\n    aiStatus.textContent = \'Checking ChatGPT result…\';\n    try {\n      const form = new FormData();\n      form.append(\'result_json\', aiJson.value || \'\');\n      const response = await fetch(\n        `/admin/discovery/${candidateId}/chatgpt-prefill/parse`,\n        {method: \'POST\', body: form, credentials: \'same-origin\'}\n      );\n      const payload = await response.json();\n      if (!response.ok) throw new Error(payload.error || \'Could not parse ChatGPT result.\');\n      if (!renderAiPeople(payload)) throw new Error(\'No person objects were found.\');\n      aiStatus.textContent = aiPeople.length > 1\n        ? `ChatGPT prefill applied. ${aiPeople.length} people found. You can add them from the list or create all non-duplicates at once.`\n        : \'ChatGPT prefill applied. Review every field before creating the pending entry.\';\n    } catch (error) {\n      aiStatus.textContent = `Could not apply ChatGPT result: ${error.message}`;\n    }\n  }\n\n  async function checkDuplicates() {\n    if (!nameInput || !warning) return;\n    const name = nameInput.value.trim();\n    if (!name) {\n      warning.style.display = \'none\';\n      warning.innerHTML = \'\';\n      return;\n    }\n\n    const params = new URLSearchParams({\n      name,\n      location: locationInput ? (locationInput.value || \'\') : \'\',\n      phone: phoneInput ? (phoneInput.value || \'\') : \'\'\n    });\n    if (ageInput && ageInput.value) params.set(\'age\', ageInput.value);\n\n    try {\n      const response = await fetch(\n        `/admin/discovery/${candidateId}/duplicate-check?${params.toString()}`,\n        {credentials: \'same-origin\'}\n      );\n      if (!response.ok) return;\n      const data = await response.json();\n      const exact = (data.people || []).filter((item) => item.exact_name);\n      const similar = (data.people || []).filter((item) => !item.exact_name && item.score >= 70);\n\n      if (!exact.length && !similar.length && !(data.pending || []).length) {\n        warning.style.display = \'none\';\n        warning.innerHTML = \'\';\n        return;\n      }\n\n      let html = \'<h3>⚠ Possible duplicate person</h3>\';\n      if (exact.length) {\n        html += \'<p><strong>The same name already exists in this disaster.</strong> If this is another link for the same person, attach the source instead of creating another person.</p>\';\n        for (const item of exact) {\n          html += `<label style="display:block; margin:8px 0"><input type="radio" name="duplicate_action" value="attach:${item.id}" required> Attach this source to ${escapeHtml(item.case_number)} — ${escapeHtml(item.name)}${item.last_seen_location ? \' — \' + escapeHtml(item.last_seen_location) : \'\'}${item.source_already_attached ? \' (source already attached)\' : \'\'}</label>`;\n        }\n        html += \'<label style="display:block; margin:8px 0"><input type="radio" name="duplicate_action" value="continue" required> This is a different person with the same name. Continue with a separate pending entry.</label>\';\n      }\n      if (similar.length) {\n        html += \'<p><strong>Similar existing cases:</strong></p><ul>\';\n        for (const item of similar) {\n          html += `<li>${escapeHtml(item.case_number)} — ${escapeHtml(item.name)} — match ${escapeHtml(item.score)}%</li>`;\n        }\n        html += \'</ul>\';\n      }\n      if ((data.pending || []).length) {\n        html += \'<p><strong>Pending submissions with this name also exist.</strong> Check them before creating another entry.</p>\';\n        if (!exact.length) {\n          html += \'<label style="display:block; margin:8px 0"><input type="radio" name="duplicate_action" value="continue" required> I reviewed the pending match and still want a separate pending entry.</label>\';\n        }\n      }\n\n      warning.innerHTML = html;\n      warning.style.display = \'block\';\n    } catch (error) {\n      // Advisory UI only. The server keeps its duplicate protections.\n    }\n  }\n\n  function scheduleCheck() {\n    clearTimeout(timer);\n    timer = setTimeout(checkDuplicates, 250);\n  }\n\n  [nameInput, ageInput, locationInput, phoneInput].forEach((element) => {\n    if (element) element.addEventListener(\'input\', scheduleCheck);\n  });\n\n  if (picker) {\n    picker.addEventListener(\'change\', function () {\n      if (this.value && nameInput) {\n        nameInput.value = this.value;\n        scheduleCheck();\n      }\n    });\n  }\n\n  if (apiRun) apiRun.addEventListener(\'click\', runBackendPrefill);\n  if (multipleAddAnother) multipleAddAnother.addEventListener(\'click\', addAnotherFromPost);\n  if (aiAddAnother) aiAddAnother.addEventListener(\'click\', addAnotherFromPost);\n  if (aiCopy) aiCopy.addEventListener(\'click\', copyAiPrompt);\n  if (aiApply) aiApply.addEventListener(\'click\', applyAiJson);\n\n  if (aiBatchForm) {\n    aiBatchForm.addEventListener(\'submit\', (event) => {\n      let raw = payloadForBatch();\n      if (!raw && aiJson) raw = aiJson.value.trim();\n      if (!raw) {\n        event.preventDefault();\n        const target = apiStatus || aiStatus;\n        if (target) target.textContent = \'Run AI Prefill first, or use the manual fallback, before batch create.\';\n        return;\n      }\n      if (aiBatchJson) aiBatchJson.value = raw;\n    });\n  }\n\n  if (aiPeoplePicker) {\n    aiPeoplePicker.addEventListener(\'change\', function () {\n      const index = Number(this.value);\n      if (Number.isInteger(index) && aiPeople[index]) applyAiPerson(aiPeople[index], index);\n    });\n  }\n\n  restoreCachedPayload();\n  checkDuplicates();\n})();\n</script>\n\n{% endblock %}\n', 'app/services/openai_prefill.py': 'from __future__ import annotations\n\nimport json\nimport os\nfrom dataclasses import dataclass\nfrom typing import Any\n\nimport httpx\n\nfrom ..models import Disaster, DiscoveryCandidate\nfrom .candidate_chatgpt_prefill import parse_candidate_chatgpt_prefill\nfrom .source_images import is_allowed_public_image_url\n\n\nOPENAI_RESPONSES_URL = "https://api.openai.com/v1/responses"\nDEFAULT_MODEL = "gpt-5-mini"\nDEFAULT_TIMEOUT_SECONDS = 45.0\n\n\nclass OpenAIPrefillError(RuntimeError):\n    pass\n\n\n@dataclass(frozen=True)\nclass OpenAIPrefillStatus:\n    available: bool\n    model: str\n    detail: str\n\n\ndef openai_prefill_status() -> OpenAIPrefillStatus:\n    key = str(os.getenv("OPENAI_API_KEY") or "").strip()\n    model = str(os.getenv("OPENAI_PREFILL_MODEL") or DEFAULT_MODEL).strip() or DEFAULT_MODEL\n    if key:\n        return OpenAIPrefillStatus(\n            available=True,\n            model=model,\n            detail="Backend AI prefill is configured. One API request extracts every explicitly named missing person from the reviewed public source.",\n        )\n    return OpenAIPrefillStatus(\n        available=False,\n        model=model,\n        detail="Set OPENAI_API_KEY on the server to enable one-click backend AI prefill. The manual copy/paste fallback remains available.",\n    )\n\n\ndef _schema() -> dict[str, Any]:\n    nullable_string: dict[str, Any] = {"type": ["string", "null"]}\n    person_properties = {\n        "name": nullable_string,\n        "name_ne": nullable_string,\n        "age": {"type": ["integer", "null"]},\n        "gender": {\n            "type": ["string", "null"],\n            "enum": ["Male", "Female", None],\n        },\n        "last_seen_date": nullable_string,\n        "last_seen_time": nullable_string,\n        "last_seen_location": nullable_string,\n        "clothing": nullable_string,\n        "identification_details": nullable_string,\n        "public_contact_number": nullable_string,\n    }\n    return {\n        "type": "object",\n        "properties": {\n            "people": {\n                "type": "array",\n                "items": {\n                    "type": "object",\n                    "properties": person_properties,\n                    "required": list(person_properties),\n                    "additionalProperties": False,\n                },\n            },\n            "source_notes": nullable_string,\n        },\n        "required": ["people", "source_notes"],\n        "additionalProperties": False,\n    }\n\n\ndef _instructions() -> str:\n    return """You extract missing-person registry fields from a public source that a human administrator has already marked relevant.\n\nUse ONLY the supplied source title, indexed snippet, public post text, OCR text, and visible WRITTEN TEXT in any supplied source image.\n\nSafety and evidence rules:\n- Never identify a person from a face or photograph.\n- If an image is supplied, use it only to read visible written/printed text. Do not infer identity, gender, age, ethnicity, clothing, location, relationship, or any other attribute from appearance.\n- Never invent or guess facts.\n- Never translate or alter a person\'s name unless that exact form is explicitly present in the supplied evidence.\n- Keep each person\'s details separate. Do not merge details between people.\n- A contact/relative named only as the person to call is not a missing person unless the evidence explicitly says that person is missing.\n- Return every explicitly named missing person in the post, including named families or multiple people.\n- Gender must be Male, Female, or null, and only when explicitly stated in textual evidence.\n- Dates must be exact Gregorian YYYY-MM-DD values only when explicitly supported. Do not convert Bikram Sambat dates or relative dates.\n- Times must be HH:MM only when explicitly stated.\n- Public phone/contact numbers may be returned only when present in the supplied public evidence.\n- Preserve useful workplace, address, family relationship, identifying, and last-seen wording in identification_details when it belongs to that specific person.\n- If no usable named missing person can be established, return an empty people array and explain the evidence limitation in source_notes.\n\nRe-scan the evidence once before returning so that no explicitly named missing person or public contact detail is missed."""\n\n\ndef _evidence_text(\n    disaster: Disaster,\n    candidate: DiscoveryCandidate,\n    *,\n    source_post_text: str,\n    ocr_text: str,\n) -> str:\n    evidence = {\n        "event": {\n            "name": disaster.name,\n            "type": disaster.disaster_type,\n            "start_date": disaster.start_date.isoformat(),\n            "affected_locations": disaster.locations(),\n        },\n        "source": {\n            "platform": candidate.platform,\n            "url": candidate.url,\n            "title": candidate.title or "",\n            "indexed_snippet": candidate.snippet or "",\n            "public_post_text": source_post_text or "",\n            "ocr_text_from_source_image": ocr_text or "",\n        },\n    }\n    return "SOURCE EVIDENCE\\n" + json.dumps(evidence, ensure_ascii=False, indent=2)\n\n\ndef _build_request_payload(\n    disaster: Disaster,\n    candidate: DiscoveryCandidate,\n    *,\n    source_post_text: str = "",\n    ocr_text: str = "",\n    source_image_url: str | None = None,\n    model: str | None = None,\n) -> dict[str, Any]:\n    content: list[dict[str, Any]] = [\n        {\n            "type": "input_text",\n            "text": _evidence_text(\n                disaster,\n                candidate,\n                source_post_text=source_post_text,\n                ocr_text=ocr_text,\n            ),\n        }\n    ]\n    if source_image_url and is_allowed_public_image_url(source_image_url):\n        content.append(\n            {\n                "type": "input_image",\n                "image_url": source_image_url,\n                "detail": "high",\n            }\n        )\n\n    return {\n        "model": model or str(os.getenv("OPENAI_PREFILL_MODEL") or DEFAULT_MODEL).strip() or DEFAULT_MODEL,\n        "instructions": _instructions(),\n        "input": [\n            {\n                "role": "user",\n                "content": content,\n            }\n        ],\n        "text": {\n            "format": {\n                "type": "json_schema",\n                "name": "missing_person_prefill",\n                "strict": True,\n                "schema": _schema(),\n            }\n        },\n        "max_output_tokens": 4000,\n        "store": False,\n    }\n\n\ndef _extract_output_text(payload: dict[str, Any]) -> str:\n    direct = payload.get("output_text")\n    if isinstance(direct, str) and direct.strip():\n        return direct.strip()\n\n    refusal_texts: list[str] = []\n    for item in payload.get("output") or []:\n        if not isinstance(item, dict) or item.get("type") != "message":\n            continue\n        for content in item.get("content") or []:\n            if not isinstance(content, dict):\n                continue\n            if content.get("type") == "output_text" and isinstance(content.get("text"), str):\n                text = content["text"].strip()\n                if text:\n                    return text\n            if content.get("type") == "refusal" and isinstance(content.get("refusal"), str):\n                refusal_texts.append(content["refusal"].strip())\n\n    if refusal_texts:\n        raise OpenAIPrefillError("The AI could not complete this extraction from the supplied evidence.")\n\n    status = str(payload.get("status") or "").strip().casefold()\n    if status == "incomplete":\n        reason = ((payload.get("incomplete_details") or {}).get("reason") or "unknown reason")\n        raise OpenAIPrefillError(f"AI extraction was incomplete: {reason}.")\n\n    raise OpenAIPrefillError("OpenAI returned no structured prefill text.")\n\n\ndef _friendly_api_error(response: httpx.Response) -> OpenAIPrefillError:\n    status = response.status_code\n    if status in {401, 403}:\n        return OpenAIPrefillError(\n            "OpenAI API authentication failed. Check the server OPENAI_API_KEY."\n        )\n    if status == 429:\n        return OpenAIPrefillError(\n            "OpenAI API rate, billing, or spending limit was reached. Check the API project balance and limits."\n        )\n    if status >= 500:\n        return OpenAIPrefillError(\n            "OpenAI is temporarily unavailable. The candidate was not changed; try again later."\n        )\n\n    detail = ""\n    try:\n        body = response.json()\n        message = ((body.get("error") or {}).get("message") or "") if isinstance(body, dict) else ""\n        if message:\n            detail = f" {str(message)[:240]}"\n    except ValueError:\n        pass\n    return OpenAIPrefillError(\n        f"OpenAI prefill request failed with HTTP {status}.{detail}".strip()\n    )\n\n\nasync def generate_openai_candidate_prefill(\n    disaster: Disaster,\n    candidate: DiscoveryCandidate,\n    *,\n    source_post_text: str = "",\n    ocr_text: str = "",\n    source_image_url: str | None = None,\n) -> dict[str, Any]:\n    key = str(os.getenv("OPENAI_API_KEY") or "").strip()\n    if not key:\n        raise OpenAIPrefillError(\n            "Backend AI prefill is not configured. Set OPENAI_API_KEY on the server first."\n        )\n\n    model = str(os.getenv("OPENAI_PREFILL_MODEL") or DEFAULT_MODEL).strip() or DEFAULT_MODEL\n    try:\n        timeout_seconds = float(os.getenv("OPENAI_PREFILL_TIMEOUT_SECONDS") or DEFAULT_TIMEOUT_SECONDS)\n    except ValueError:\n        timeout_seconds = DEFAULT_TIMEOUT_SECONDS\n\n    request_payload = _build_request_payload(\n        disaster,\n        candidate,\n        source_post_text=source_post_text,\n        ocr_text=ocr_text,\n        source_image_url=source_image_url,\n        model=model,\n    )\n\n    headers = {\n        "Authorization": f"Bearer {key}",\n        "Content-Type": "application/json",\n    }\n\n    try:\n        async with httpx.AsyncClient(timeout=httpx.Timeout(timeout_seconds, connect=10.0)) as client:\n            response = await client.post(\n                OPENAI_RESPONSES_URL,\n                headers=headers,\n                json=request_payload,\n            )\n    except httpx.HTTPError as exc:\n        raise OpenAIPrefillError(\n            "Could not reach OpenAI for AI prefill. The candidate was not changed."\n        ) from exc\n\n    if response.status_code != 200:\n        raise _friendly_api_error(response)\n\n    try:\n        api_payload = response.json()\n    except ValueError as exc:\n        raise OpenAIPrefillError("OpenAI returned an unreadable response.") from exc\n\n    output_text = _extract_output_text(api_payload)\n    try:\n        normalized = parse_candidate_chatgpt_prefill(output_text)\n    except ValueError as exc:\n        raise OpenAIPrefillError(\n            "OpenAI returned structured output that could not be normalized safely."\n        ) from exc\n\n    if not normalized.get("people"):\n        raise OpenAIPrefillError(\n            normalized.get("source_notes")\n            or "The AI did not find an explicitly named missing person in the supplied evidence."\n        )\n\n    usage = api_payload.get("usage") if isinstance(api_payload.get("usage"), dict) else {}\n    return {\n        **normalized,\n        "model": str(api_payload.get("model") or model),\n        "usage": {\n            "input_tokens": int(usage.get("input_tokens") or 0),\n            "output_tokens": int(usage.get("output_tokens") or 0),\n            "total_tokens": int(usage.get("total_tokens") or 0),\n        },\n    }\n', 'tests/test_backend_openai_prefill_upgrade.py': 'import json\nfrom datetime import date\nfrom pathlib import Path\n\nfrom app.database import SessionLocal\nfrom app.models import Disaster, DiscoveryCandidate\nfrom app.services.openai_prefill import (\n    _build_request_payload,\n    _extract_output_text,\n    openai_prefill_status,\n)\n\n\ndef _event_and_candidate():\n    disaster = Disaster(\n        code="RF",\n        name="Rasuwa Flood",\n        disaster_type="flood",\n        start_date=date(2026, 8, 26),\n        affected_locations="Rasuwa\\nTimure",\n    )\n    candidate = DiscoveryCandidate(\n        id=10,\n        disaster_id=1,\n        platform="facebook",\n        query="q",\n        url="https://facebook.com/example/posts/123",\n        title="Two people missing",\n        snippet="A Person and B Person are missing in Timure.",\n        status="relevant",\n    )\n    return disaster, candidate\n\n\ndef test_openai_request_uses_strict_structured_output_and_public_evidence_only():\n    disaster, candidate = _event_and_candidate()\n    payload = _build_request_payload(\n        disaster,\n        candidate,\n        source_post_text="A Person age 30. B Person age 44.",\n        ocr_text="Contact 9812345678",\n        source_image_url="https://scontent.xx.fbcdn.net/example.jpg",\n        model="gpt-5-mini",\n    )\n    assert payload["model"] == "gpt-5-mini"\n    assert payload["store"] is False\n    assert payload["text"]["format"]["type"] == "json_schema"\n    assert payload["text"]["format"]["strict"] is True\n    assert payload["text"]["format"]["schema"]["properties"]["people"]["type"] == "array"\n    content = payload["input"][0]["content"]\n    assert content[0]["type"] == "input_text"\n    assert "9812345678" in content[0]["text"]\n    assert any(item.get("type") == "input_image" for item in content)\n    assert "Never identify a person from a face" in payload["instructions"]\n\n\ndef test_output_text_is_read_from_responses_api_message():\n    raw = json.dumps({"people": [{"name": "A Person"}], "source_notes": None})\n    payload = {\n        "status": "completed",\n        "output": [\n            {\n                "type": "message",\n                "content": [{"type": "output_text", "text": raw}],\n            }\n        ],\n    }\n    assert _extract_output_text(payload) == raw\n\n\ndef test_openai_status_requires_server_key(monkeypatch):\n    monkeypatch.delenv("OPENAI_API_KEY", raising=False)\n    assert openai_prefill_status().available is False\n    monkeypatch.setenv("OPENAI_API_KEY", "test-key-not-real")\n    monkeypatch.setenv("OPENAI_PREFILL_MODEL", "gpt-5-mini")\n    status = openai_prefill_status()\n    assert status.available is True\n    assert status.model == "gpt-5-mini"\n\n\ndef test_review_template_has_one_click_prefill_and_add_another_button():\n    template = Path("app/templates/admin_discovery_review.html").read_text(encoding="utf-8")\n    assert "AI Prefill All People" in template\n    assert "/openai-prefill" in template\n    assert "+ Add another missing person from this post" in template\n    assert "sessionStorage" in template\n    assert "Create All Non-Duplicate People as Pending Entries" in template\n    assert "Manual ChatGPT fallback" in template\n\n\ndef test_backend_prefill_endpoint_returns_all_people_without_manual_json(admin_client, monkeypatch):\n    admin_client.post(\n        "/admin/events",\n        data={\n            "code": "RF",\n            "name": "Rasuwa Flood",\n            "disaster_type": "flood",\n            "start_date": "2026-08-26",\n            "affected_locations": "Rasuwa\\nTimure",\n            "active": "on",\n        },\n        follow_redirects=False,\n    )\n    with SessionLocal() as db:\n        db.add(\n            DiscoveryCandidate(\n                disaster_id=1,\n                platform="facebook",\n                query="q",\n                url="https://facebook.com/example/posts/123",\n                title="Two people missing",\n                snippet="A Person and B Person are missing in Timure.",\n                status="relevant",\n            )\n        )\n        db.commit()\n\n    async def fake_prefill(*args, **kwargs):\n        return {\n            "people": [\n                {\n                    "name": "A Person", "name_ne": None, "age": 30, "gender": None,\n                    "last_seen_date": None, "last_seen_time": None,\n                    "last_seen_location": "Timure", "clothing": None,\n                    "identification_details": "Works at example project",\n                    "public_contact_number": "9812345678",\n                },\n                {\n                    "name": "B Person", "name_ne": None, "age": 44, "gender": None,\n                    "last_seen_date": None, "last_seen_time": None,\n                    "last_seen_location": "Timure", "clothing": None,\n                    "identification_details": None,\n                    "public_contact_number": "9812345678",\n                },\n            ],\n            "source_notes": "Two explicitly named missing people.",\n            "model": "gpt-5-mini",\n            "usage": {"input_tokens": 100, "output_tokens": 50, "total_tokens": 150},\n        }\n\n    async def fake_text(url):\n        return "A Person and B Person are missing in Timure. Contact 9812345678."\n\n    async def fake_image(url):\n        return None\n\n    monkeypatch.setattr("app.routes.admin.generate_openai_candidate_prefill", fake_prefill)\n    monkeypatch.setattr("app.routes.admin.discover_public_post_text", fake_text)\n    monkeypatch.setattr("app.routes.admin.discover_public_post_image", fake_image)\n\n    response = admin_client.post("/admin/discovery/1/openai-prefill")\n    assert response.status_code == 200\n    body = response.json()\n    assert [person["name"] for person in body["people"]] == ["A Person", "B Person"]\n    assert body["model"] == "gpt-5-mini"\n'}


def canonical(text: str) -> str:
    return text.replace("\r\n", "\n").replace("\r", "\n")


def digest(path: Path) -> str:
    return hashlib.sha256(
        canonical(path.read_text(encoding="utf-8")).encode("utf-8")
    ).hexdigest()


def main() -> int:
    root = Path.cwd()

    for rel, expected in EXPECTED.items():
        path = root / rel
        if not path.is_file():
            print(f"ABORTED: expected file missing: {rel}")
            print("No files were changed.")
            return 2
        actual = digest(path)
        if actual != expected:
            print(f"ABORTED: local file differs from the reviewed version: {rel}")
            print(f"Expected SHA-256: {expected}")
            print(f"Actual SHA-256:   {actual}")
            print("No files were changed.")
            return 3

    for rel in (
        "app/services/openai_prefill.py",
        "tests/test_backend_openai_prefill_upgrade.py",
    ):
        if (root / rel).exists():
            print(f"ABORTED: new target already exists: {rel}")
            print("No files were changed.")
            return 4

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    backup = root / f".backend-ai-prefill-backup-{stamp}"

    for rel in EXPECTED:
        source = root / rel
        target = backup / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)

    for rel, content in CONTENTS.items():
        target = root / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8", newline="\n")

    print("BACKEND AI PREFILL UPGRADE APPLIED")
    print(f"Backup: {backup}")
    print("")
    print("Added / changed:")
    print("- one-click OpenAI API prefill after a source is marked Relevant")
    print("- one backend request extracts every explicitly named missing person")
    print("- strict Structured Outputs remove manual JSON formatting failures")
    print("- public source image may be supplied only for reading written text")
    print("- first extracted person is pasted directly into the existing form")
    print("- all extracted people appear as Add / review buttons")
    print("- Add another missing person reuses the same extraction")
    print("- browser-tab cache avoids another AI call after creating the first person")
    print("- existing batch-create-all workflow now receives the API result automatically")
    print("- manual ChatGPT copy/paste remains as a fallback")
    print("- no database migration and no new Python package required")
    print("")
    print("Runtime requirement: set OPENAI_API_KEY on the server.")
    print("Optional: OPENAI_PREFILL_MODEL (default gpt-5-mini).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
